-- Code generated by game-db import. DO NOT EDIT.
-- Source: Sheets Dump/. Regenerate with `make import`.
-- sudden_death_questions: 276 questions for subject accounts.

MERGE INTO sudden_death_questions AS t
USING (
    SELECT v.question_code, c.id AS chapter_id, v.prompt, v.option_a, v.option_b, v.correct_option, v.difficulty, v.points, v.hint, v.explanation
    FROM (VALUES
        ('acc11-01-sd-0001', 1, 'During Chandragupta Maurya''s regime in India, which minister wrote ''Arthashastra'', containing references to maintaining accounting records?', 'Kautilya', 'Aryabhata', 'a', 1, 3, 'Recall the strategist also known as Chanakya.', 'Kautilya wrote the Arthashastra, which includes references to accounting records. Aryabhata was a mathematician and astronomer, not the author of this work.'),
        ('acc11-01-sd-0002', 1, 'Which specialized branch of accounting emerged in the 20th century primarily due to the need for financial analysis to support managerial decision-making?', 'Forensic Accounting', 'Management Accounting', 'b', 1, 3, 'Think of accounting used for internal decisions.', 'Management accounting supports managerial planning and decision-making. Forensic accounting focuses on investigating financial irregularities and disputes.'),
        ('acc11-01-sd-0003', 1, 'Which scholar defined book-keeping simply as ''an art of recording business dealings in a set of books''?', 'J. R. Batliboi', 'Luca Pacioli', 'a', 1, 3, 'Recall the scholar associated with this concise definition.', 'J. R. Batliboi defined book-keeping as the art of recording business dealings in books. Luca Pacioli is associated with the development and publication of double-entry bookkeeping.'),
        ('acc11-01-sd-0004', 1, 'According to Nocth Cott, book-keeping is specifically defined as an art of recording in the books of accounts:', 'The managerial forecasts and production estimates', 'The monetary aspects of commercial or financial transactions', 'b', 1, 3, 'Focus on transactions expressed in money.', 'Nocth Cott''s definition focuses on recording the monetary aspects of commercial or financial transactions. Managerial forecasts and production estimates are planning information, not the transactions described in this definition.'),
        ('acc11-01-sd-0005', 1, 'According to R. N. Carter, book-keeping is the science and art of correctly recording in books of accounts all those transactions that result in:', 'Transfer of money or money''s worth', 'Transfer of legal title of real estate', 'a', 1, 3, 'Think about exchanges involving money or its equivalent.', 'R. N. Carter''s definition refers to transactions involving the transfer of money or money''s worth. A transfer of legal title to real estate alone does not capture the definition.'),
        ('acc11-01-sd-0006', 1, 'Who defined Accountancy as ''the entire body of the theory and process of accounting''?', 'R. N. Carter', 'Kohler', 'b', 1, 3, 'Recall the accounting scholar associated with this definition.', 'Kohler defined accountancy as the entire body of accounting theory and process. R. N. Carter is associated with a definition of book-keeping.'),
        ('acc11-01-sd-0007', 1, 'Which two primary qualitative characteristics make accounting information useful for decision-making?', 'Relevance and Reliability', 'Complexity and Confidentiality', 'a', 2, 3, 'Look for the qualities that make information decision-useful.', 'Relevance and reliability are key qualitative characteristics of useful accounting information. Complexity and confidentiality do not describe these core qualities.'),
        ('acc11-01-sd-0008', 1, 'What core principle does ''Comparability'' imply when presenting accounting information?', 'Changing accounting methods every fiscal quarter', 'Reporting like things in a similar fashion and unlike things differently', 'b', 2, 3, 'Think about consistency in how similar items are reported.', 'Comparability means reporting like things in a similar way and unlike things differently. Changing methods every quarter makes comparisons harder rather than supporting them.'),
        ('acc11-01-sd-0009', 1, 'A transaction in which cash is not paid or received immediately at the time of the transaction, but at a later date, is termed as:', 'Credit Transaction', 'Barter Transaction', 'a', 1, 3, 'The payment happens after the transaction date.', 'A credit transaction involves payment at a later date. A barter transaction exchanges goods or services without using money as the medium of exchange.'),
        ('acc11-01-sd-0010', 1, 'A brief explanation of a business transaction written in brackets below a journal entry, usually starting with ''Being'' or ''For'', is known as:', 'Voucher', 'Narration', 'b', 1, 3, 'Look for the note explaining a journal entry.', 'Narration is the brief explanation accompanying a journal entry. A voucher is a supporting document for a transaction, not the explanatory note beneath the entry.'),
        ('acc11-01-sd-0011', 1, 'If a proprietor pays his son''s college tuition fees or his personal residential mobile bill from the business bank account, this transaction is classified as:', 'Drawings', 'Capital Expenditure', 'a', 2, 3, 'Consider the owner''s personal use of business funds.', 'Personal payments made from business funds are treated as drawings. Capital expenditure is spending on acquiring or improving long-term assets.'),
        ('acc11-01-sd-0012', 1, 'A customer who owes money to the business for goods purchased on credit is called a ________, whereas a supplier to whom the business owes money is called a ________.', 'Creditor; Debtor', 'Debtor; Creditor', 'b', 1, 3, 'Identify who owes the business and who the business owes.', 'A debtor owes money to the business, while a creditor is owed money by the business. The reversed pair assigns each term to the wrong party.'),
        ('acc11-01-sd-0013', 1, 'An irrecoverable amount from a debtor is known as ''Bad Debts''. In accounting, Bad Debts are classified as:', 'Revenue Loss', 'Fictitious Asset', 'a', 1, 3, 'Think of the effect of an amount that cannot be recovered.', 'Bad debts are a revenue loss because an amount owed by a debtor is irrecoverable. A fictitious asset is a different accounting classification and does not describe this loss.'),
        ('acc11-01-sd-0014', 1, 'Goodwill is defined as the reputation of a business expressed in terms of money. What type of asset is Goodwill?', 'Fictitious Asset', 'Intangible Asset', 'b', 1, 3, 'Goodwill has value but no physical substance.', 'Goodwill is an intangible asset because it represents business reputation without physical form. A fictitious asset is not the category used for goodwill.'),
        ('acc11-01-sd-0015', 1, 'A company adopts the fixed installment method for charging depreciation from year to year. Which accounting concept does this practice illustrate?', 'Realization Concept', 'Consistency Concept', 'b', 2, 3, 'Think about applying the same accounting method over time.', 'Using the fixed installment method consistently from year to year illustrates the consistency concept. The realization concept concerns when revenue is recognized.'),
        ('acc11-01-sd-0016', 1, 'Which basic accounting assumption presumes that an enterprise will continue its operational existence for the foreseeable future and not be liquidated?', 'Going Concern Concept', 'Periodicity Concept', 'a', 1, 3, 'Consider the assumption that the business will continue operating.', 'The going concern concept assumes the enterprise will continue operating for the foreseeable future. The periodicity concept divides business activity into accounting periods.'),
        ('acc11-01-sd-0017', 1, 'International Financial Reporting Standards (IFRS) are formulated and issued by which international body?', 'World Bank Financial Division', 'International Accounting Standard Board (IASB)', 'b', 1, 3, 'Recall the international body responsible for IFRS.', 'The International Accounting Standards Board (IASB) issues IFRS. The World Bank''s financial division is not the standard-setting body for IFRS.'),
        ('acc11-01-sd-0018', 1, 'According to AS-2, how should inventories in general be valued in financial statements?', 'At the lower of historical cost and net realizable value', 'At replacement cost only', 'a', 2, 3, 'Compare cost with the amount expected to be realized.', 'AS-2 generally values inventory at the lower of historical cost and net realizable value. Replacement cost alone is not the required general valuation basis.'),
        ('acc11-01-sd-0019', 1, 'Under AS-22, tax expenses for the period included in determining net profit or loss comprise which components?', 'Sales tax and excise duty', 'Current tax and deferred tax', 'b', 2, 3, 'Consider both present and future tax effects.', 'The tax expense includes current tax and deferred tax. Sales tax and excise duty are transaction taxes, not the two components specified here.'),
        ('acc11-01-sd-0020', 1, 'In financial accounting, what type of account is a ''Bank Overdraft''?', 'Current Liability', 'Owners'' Equity', 'a', 1, 3, 'An overdraft means the bank account has a negative balance.', 'A bank overdraft is a current liability because the business owes the bank. It is not owners'' equity.'),
        ('acc11-01-sd-0021', 1, 'What two items are included in Net Worth?', 'Capital and Reserves', 'Gross Sales and Cost of Goods Sold', 'a', 2, 3, 'Think of the owner''s accumulated stake in the business.', 'Net worth includes capital and reserves. Gross sales and cost of goods sold are used in determining gross profit, not net worth.'),
        ('acc11-02-sd-0001', 2, 'What is the foundational principle underlying every business transaction in the Double Entry System?', 'Transactions are recorded only when profit or loss is realized.', 'Every transaction has two aspects where one party is the receiver of the benefit and the other is the giver.', 'b', 1, 3, 'Think about the two-sided effect of each transaction.', 'Every transaction has two aspects: one party receives a benefit and another gives it. Transactions do not affect only cash, nor are two-fold entries limited to credit transactions.'),
        ('acc11-02-sd-0002', 2, 'The Indian system of recording accounting information in languages like Marathi, Hindi, Urdu, and Gujarati is also known as:', 'Mahajani Deshinama System', 'Double Entry System', 'a', 1, 3, 'Recall the traditional indigenous Indian accounting method.', 'The method is called Mahajani Deshinama System. It is not the English System.'),
        ('acc11-02-sd-0003', 2, 'In the Indian System (Mahajani Deshinama), transactions are maintained in long books known as:', 'Journal and Ledger', 'Bahi-Khata and Kird', 'b', 1, 3, 'Recall the traditional names for long accounting books.', 'The traditional books are Bahi-Khata and Kird. Journal and Ledger are books used in the formal accounting system.'),
        ('acc11-02-sd-0004', 2, 'Why is the Indian System of accounting categorized as an unscientific and conventional method?', 'It is not based on the principles of the Double Entry System.', 'It does not record transactions in any systematic books.', 'a', 2, 3, 'Consider its relationship to double-entry principles.', 'The Indian conventional system is considered unscientific because it is not based on double-entry principles. It does use systematic records, so that is not the reason.'),
        ('acc11-02-sd-0005', 2, 'Which accounts are exclusively maintained under the Single Entry System?', 'Expenses accounts and Income accounts only', 'Cash book and Personal accounts', 'b', 1, 3, 'Recall which records are kept in single-entry bookkeeping.', 'Single Entry System maintains a cash book and personal accounts. Real and nominal accounts are not exclusively maintained.'),
        ('acc11-02-sd-0006', 2, 'Who defined Double Entry by stating: ''Every business transaction has a two fold effect and that it affects two accounts in opposite directions...''?', 'J.R. Batliboi', 'R.N. Carter', 'a', 1, 3, 'Recall the accounting author associated with this definition.', 'J.R. Batliboi gave this definition of double entry. R.N. Carter is associated with a definition of an account.'),
        ('acc11-02-sd-0007', 2, 'Which of the following is a basic principle of the Double Entry Book-keeping System?', 'Every debit has an equal and corresponding credit of the same amount.', 'Personal accounts are credited when they receive a benefit.', 'a', 1, 3, 'Think of the equality between the two sides of an entry.', 'Each debit has an equal corresponding credit of the same amount. Debits do not have to exceed credits.'),
        ('acc11-02-sd-0008', 2, 'Which advantage of Double Entry Book-keeping ensures that arithmetical accuracy of accounting work can be checked?', 'Accuracy', 'Common Acceptance', 'a', 1, 3, 'Think of the benefit that allows arithmetical checking.', 'Accuracy is the advantage that allows arithmetical accuracy to be checked. Common acceptance refers to widespread use.'),
        ('acc11-02-sd-0009', 2, 'Why does the Double Entry System enjoy ''Common Acceptance'' across financial institutions and government authorities?', 'Because it eliminates the need to balance ledger accounts.', 'Because it follows universal accounting principles.', 'b', 2, 3, 'Consider why institutions widely use the system.', 'It follows universal accounting principles, which supports common acceptance. It does not eliminate the need to balance ledgers.'),
        ('acc11-02-sd-0010', 2, 'What is the Conventional Accounting System primarily based on?', 'Practicability and rules used by common agreement', 'International Financial Reporting Standards only', 'a', 1, 3, 'Recall the role of practicality and convention.', 'The conventional accounting system is based on practicability and rules accepted by common agreement, not exclusively on legislation.'),
        ('acc11-02-sd-0011', 2, 'In standard accounting format, which sides represent Debit (Dr.) and Credit (Cr.) respectively?', 'Debit is the right-hand side and Credit is the left-hand side.', 'Debit is the left-hand side and Credit is the right-hand side.', 'b', 1, 3, 'Recall the standard left-right layout of an account.', 'Debit is on the left and Credit is on the right. The top and bottom are not the debit and credit sides.'),
        ('acc11-02-sd-0012', 2, 'Accounts relating to individual human beings such as Sunita''s A/c, Ashok''s A/c, or Suha''s A/c are classified as:', 'Artificial Personal Accounts', 'Natural Personal Accounts', 'b', 1, 3, 'Think of accounts for individual human beings.', 'Natural Personal Accounts relate to individual human beings. Artificial Personal Accounts relate to organizations or bodies.'),
        ('acc11-02-sd-0013', 2, 'Which of the following accounts is an example of an Artificial Personal Account?', 'Patent A/c', 'Pune Municipal Corporation A/c', 'b', 2, 3, 'Look for an organization created or recognized by law.', 'Pune Municipal Corporation is an artificial personal account. Sushma''s account represents a natural person.'),
        ('acc11-02-sd-0014', 2, 'Accounts relating to outstanding and prepaid expenses or accrued incomes are categorized as:', 'Representative Personal Accounts', 'Nominal Accounts', 'a', 2, 3, 'Consider prepaid and outstanding items.', 'These are Representative Personal Accounts. Nominal Accounts record expenses, losses, incomes, and gains.'),
        ('acc11-02-sd-0015', 2, 'Real Accounts represent:', 'Expenses, losses, incomes, and gains', 'Assets and properties owned by the business', 'b', 1, 3, 'Think of the property owned by a business.', 'Real Accounts represent assets and properties owned by the business. Expenses and incomes are nominal accounts.'),
        ('acc11-02-sd-0016', 2, 'Which of the following is categorized as an Intangible Real Account?', 'Machinery A/c', 'Goodwill A/c', 'b', 1, 3, 'Identify a non-physical asset with monetary value.', 'Goodwill is an intangible real asset. Machinery is a tangible real asset.'),
        ('acc11-02-sd-0017', 2, 'Assets that can be seen, touched, and felt (such as Machinery, Motor Car, and Stock of Goods) are called:', 'Tangible Real Accounts', 'Representative Personal Accounts', 'a', 1, 3, 'Focus on assets that have a physical form.', 'Tangible Real Accounts cover assets that can be seen, touched, and felt. Nominal Accounts concern expenses, losses, incomes, and gains.'),
        ('acc11-02-sd-0018', 2, 'Accounts of expenses, losses, income, and gains are known as:', 'Nominal Accounts', 'Real Accounts', 'a', 1, 3, 'Recall the traditional account type for earnings and costs.', 'Nominal Accounts cover expenses, losses, incomes, and gains. Personal Accounts relate to persons or entities.'),
        ('acc11-02-sd-0019', 2, 'Which of the following represents an Income/Gain under Nominal Accounts?', 'Depreciation A/c', 'Commission Received A/c', 'b', 2, 3, 'Distinguish revenue from an expense.', 'Commission Received is income or gain. Stationery is an expense, not income.'),
        ('acc11-02-sd-0020', 2, 'What is the Golden Rule of Debit and Credit for Personal Accounts?', 'Debit the receiver, Credit the giver', 'Debit what comes in, Credit what goes out', 'a', 1, 3, 'Recall the rule for the person receiving a benefit.', 'For Personal Accounts, debit the receiver and credit the giver. The coming-in/going-out rule applies to Real Accounts.'),
        ('acc11-02-sd-0021', 2, 'What is the Golden Rule of Debit and Credit for Real Accounts?', 'Debit the giver, Credit the receiver', 'Debit what comes in, Credit what goes out', 'b', 1, 3, 'Think about assets entering or leaving the business.', 'For Real Accounts, debit what comes in and credit what goes out. The receiver/giver rule applies to Personal Accounts.'),
        ('acc11-02-sd-0022', 2, 'What is the Golden Rule of Debit and Credit for Nominal Accounts?', 'Debit all expenses and losses, Credit all incomes and gains', 'Debit the receiver, Credit the giver', 'a', 1, 3, 'Recall how expenses and incomes are treated.', 'For Nominal Accounts, debit expenses and losses and credit incomes and gains. The receiver/giver rule applies to Personal Accounts.'),
        ('acc11-02-sd-0023', 2, 'Under the Modern Approach, accounts are divided into which five categories?', 'Assets, Liabilities, Capital, Expenses/Losses, and Revenues/Gains', 'Personal, Real, Nominal, Tangible, and Intangible', 'a', 1, 3, 'Recall the five modern account categories.', 'The Modern Approach uses Assets, Liabilities, Capital, Expenses/Losses, and Revenues/Gains. Personal, Real, and Nominal belong to traditional classification.'),
        ('acc11-02-sd-0024', 2, 'Under the Modern Approach, how are increases and decreases in Assets and Expenses recorded?', 'Both increase and decrease are debited.', 'Increase is debited and decrease is credited.', 'b', 2, 3, 'Remember the normal debit effect for assets and expenses.', 'Increases in assets and expenses are debited; decreases are credited. Crediting increases is not the rule for these categories.'),
        ('acc11-02-sd-0025', 2, 'Under the Modern Approach, what is the rule for recording changes in Liabilities, Capital, and Revenues?', 'Increase is credited and decrease is debited.', 'Increase is debited and decrease is credited.', 'a', 2, 3, 'Think about the normal credit effect of obligations and earnings.', 'Increases in liabilities, capital, and revenues are credited; decreases are debited. An increase is not debited.'),
        ('acc11-02-sd-0026', 2, 'How is ''Bank Overdraft A/c'' classified under the Modern Approach?', 'Asset Account', 'Liability Account', 'b', 2, 3, 'Consider whether an overdraft is owned or owed.', 'A bank overdraft is a liability because the business owes money to the bank. It is not an asset.'),
        ('acc11-02-sd-0027', 2, 'Under the Modern Approach, ''Repairs and Maintenance A/c'' and ''Audit Fees A/c'' are classified under:', 'Revenues and Gains', 'Expenses and Losses', 'b', 1, 3, 'Classify routine costs incurred to operate a business.', 'Repairs and maintenance and audit fees are expenses/losses. They are not assets or revenues.'),
        ('acc11-02-sd-0028', 2, 'What does the fundamental Accounting Equation state?', 'Assets = Liabilities + Capital', 'Liabilities = Assets + Capital', 'a', 1, 3, 'Recall the relationship between assets, liabilities, and capital.', 'The accounting equation is Assets = Liabilities + Capital. Capital is not added to assets and liabilities.'),
        ('acc11-03-sd-0001', 3, 'Which of the following is explicitly listed in the chapter as a legal or statutory utility of accounting documents?', 'To summarize the ledger balances at the close of an accounting year', 'To act as legal evidence and proof supporting business transactions recorded in the books', 'b', 1, 3, 'A short hint: think about the evidence supporting recorded transactions.', 'A source document provides evidence for a business transaction. Ledger balances are summarized in the ledger or financial reports, not by the source document.'),
        ('acc11-03-sd-0002', 3, 'An internal voucher is prepared by an organisation primarily when:', 'Debit Note', 'Voucher', 'b', 2, 3, 'A short hint: identify the document that supports a payment.', 'A voucher supports a payment and serves as evidence that money was paid. A debit note records a claim or adjustment, not proof of payment.'),
        ('acc11-03-sd-0003', 3, 'Which of the following documents is categorized in the chapter as an ''External Voucher''?', 'Goods are purchased on credit from a registered supplier', 'No third-party receipt can be obtained as proof for a transaction, such as taxi or auto fare', 'b', 2, 3, 'Think about transactions for which an outside receipt is unavailable.', 'An internal voucher is prepared when external documentary proof is unavailable. Credit purchases are generally supported by an external invoice.'),
        ('acc11-03-sd-0004', 3, 'What is the specific purpose of a ''Journal Voucher'' as stated in the text?', 'Tax Invoice received from a seller for purchasing stationery', 'Bus fare slip prepared internally by the firm''s cashier', 'a', 1, 3, 'Consider which document originates outside the business.', 'A tax invoice received from a seller is an external voucher. A fare slip prepared by the firm''s cashier is an internal document.'),
        ('acc11-03-sd-0005', 3, 'On the basis of which document are entries directly recorded in the Cash Book?', 'It is the basic/original voucher on the basis of which transactions are journalised in the Journal book', 'It replaces the Cash Book for recording all cash inflows and outflows', 'a', 1, 3, 'Recall the voucher used as the basis for journal entries.', 'A journal voucher supports transactions entered in the Journal. It does not replace the Cash Book, which records cash and bank transactions.'),
        ('acc11-03-sd-0006', 3, 'For a buyer, a Tax Invoice received from the supplier is termed as a/an:', 'Journal Voucher', 'Cash Voucher', 'b', 2, 3, 'Think about the voucher that supports cash transactions.', 'Cash transactions are entered in the Cash Book on the basis of cash vouchers. A journal voucher supports entries made in the Journal.'),
        ('acc11-03-sd-0007', 3, 'What information does a seller communicate to a customer through a Credit Memo?', 'Sales Invoice or Outward Invoice', 'Purchase Invoice or Inward Invoice', 'b', 2, 3, 'Think from the buyer''s point of view.', 'A buyer records the supplier''s tax invoice as a purchase or inward invoice. A sales or outward invoice is issued by the seller.'),
        ('acc11-03-sd-0008', 3, 'When a customer makes a payment on a future date for credit purchases, the seller acknowledges the receipt of money by issuing a:', 'Confirmation that cash has been physically received at the counter', 'Details of goods sold on credit for which a certain amount becomes due from the customer', 'b', 1, 3, 'Think about what the seller communicates when credit creates an amount due.', 'A credit memo communicates details of credit sales and the amount due from the customer. Confirmation of cash received is associated with a receipt.'),
        ('acc11-03-sd-0009', 3, 'According to the definition in the chapter, a cheque is an order that is:', 'Receipt', 'Credit Memo', 'a', 1, 3, 'Think about the document acknowledging money received.', 'A receipt acknowledges payment received. A credit memo communicates credit-sale details and the amount due.'),
        ('acc11-03-sd-0010', 3, 'In the context of a cheque, who is the ''Drawee''?', 'Written and unconditional, directing a specific banker to pay on demand', 'Oral or written, payable only after three months of issuance', 'a', 1, 3, 'Recall the defining features of a cheque.', 'A cheque is a written, unconditional instruction to a banker to pay on demand. It is not an oral instruction or one that must wait three months.'),
        ('acc11-03-sd-0011', 3, 'How can a Bearer Cheque be converted into an Order Cheque?', 'The bank on whom the cheque is drawn', 'The person who writes and signs the cheque', 'a', 2, 3, 'Identify the party instructed to make the payment.', 'The drawee is the bank directed to pay the cheque. The person who writes and signs it is the drawer.'),
        ('acc11-03-sd-0012', 3, 'What is the legal effect of drawing two parallel transverse lines on the face of a cheque without extra words?', 'By striking off the word ''Bearer'' on the cheque', 'By drawing two parallel transverse lines across the left top corner', 'a', 2, 3, 'Think about the wording that changes who may receive payment.', 'Striking out “Bearer” can convert a bearer cheque into an order cheque. Two parallel lines cross the cheque to indicate crossing, not this conversion.'),
        ('acc11-03-sd-0013', 3, 'A cheque with two parallel transverse lines containing the words ''Account Payee'' ensures that:', 'The cheque becomes payable in cash to any person holding it at the counter', 'The cheque must be deposited into a bank account and cannot be encashed directly over the counter', 'b', 2, 3, 'Think about the effect of crossing a cheque.', 'Crossing generally requires the cheque to be collected through a bank account rather than cashed over the counter. An uncrossed bearer cheque may be payable over the counter.'),
        ('acc11-03-sd-0014', 3, 'The English word ''Journal'' is derived from which French word, and what is its meaning?', 'The cheque can be freely transferred and endorsed to third parties multiple times', 'The amount is credited strictly to the payee''s specific bank account', 'b', 1, 3, 'Focus on the words written between the parallel lines.', 'An Account Payee crossing directs the amount to the named payee''s account. It is not intended for free transfer to third parties.'),
        ('acc11-03-sd-0015', 3, 'Who defined a Journal as ''a book, employed to classify or sort out transactions in a form convenient for their subsequent entry in the Ledger''?', '''JOURNALIER'', which means ''Book''', '''JOUR'', which means ''Day''', 'b', 1, 3, 'Recall the French root of the accounting term.', '“Journal” comes from the French word “jour,” meaning day. “Journalier” is not the word meaning day.'),
        ('acc11-03-sd-0016', 3, 'According to Eric Kohler''s definition in ''A Dictionary for Accountant'', a Journal is:', 'R.N. Carter', 'L.C. Cropper', 'b', 2, 3, 'Recall which accounting author gave this definition.', 'L.C. Cropper is associated with this definition of a Journal. R.N. Carter gave a different definition.'),
        ('acc11-03-sd-0017', 3, 'In Eric Kohler''s definition in ''A Dictionary for Accountant'', a Journal is:', 'The book of original entry in which are recorded transactions not provided for in specialised journals', 'A permanent register containing only nominal and real accounts', 'a', 1, 3, 'Think about the Journal''s role among books of original entry.', 'The Journal is a book of original entry for transactions not recorded in specialized journals. It is not a register limited to nominal and real accounts.'),
        ('acc11-03-sd-0018', 3, 'Transactions are recorded in the Journal in which specific arrangement?', 'Ledger', 'Journal Proper', 'a', 1, 3, 'Think about the book where accounts are maintained after journalising.', 'The Ledger is a secondary book where transactions are classified into accounts. Journal Proper is a book of original entry.'),
        ('acc11-03-sd-0019', 3, 'In the standard specimen of a Journal, how many columns are there, and what are their headers from left to right?', 'Chronological order (date-wise in order of occurrence)', 'Alphabetical order based on customer name', 'a', 1, 3, 'Think about how transactions are ordered by time.', 'Journal transactions are recorded chronologically, by date of occurrence. They are not arranged alphabetically by customer.'),
        ('acc11-03-sd-0020', 3, 'What is ''Narration'' in a journal entry, and how should it begin?', '4 columns: Date, Particulars, Folio, Net Amount (₹)', '5 columns: Date, Particulars, L.F., Debit Amount (₹), Credit Amount (₹)', 'b', 1, 3, 'Recall the standard journal''s column layout.', 'The standard Journal specimen has five columns: Date, Particulars, Ledger Folio, Debit Amount, and Credit Amount. The four-column layout listed is not the standard format.'),
        ('acc11-03-sd-0021', 3, 'Why is the Ledger Folio (L.F.) column left blank at the exact time of journalising?', 'The ledger page reference written on top of the date column, beginning with ''Ref.''', 'A brief explanation of the journal entry written in brackets, beginning with the word ''Being''', 'b', 2, 3, 'Think about the explanatory note written below an entry.', 'Narration briefly explains the journal entry and commonly begins with “Being.” A ledger page reference belongs in the Ledger Folio column.'),
        ('acc11-03-sd-0022', 3, 'To distinguish the Ledger Folio numbers from amounts, the chapter mentions that folio numbers may be written in:', 'Because the ledger is prepared prior to writing the journal', 'Because the page number in the ledger is entered only when the entry is actually posted to the ledger', 'b', 1, 3, 'Think about when ledger posting takes place.', 'The Ledger Folio number is filled in when the journal entry is posted to the ledger. The ledger is not prepared before the journal as a reason for leaving the column blank.'),
        ('acc11-03-sd-0023', 3, 'When casting a page of the Journal, how are totals carried forward and brought forward to the next page?', 'Green ink', 'Red ink', 'b', 2, 3, 'Recall the suggested way to distinguish folio numbers from amounts.', 'Ledger Folio numbers may be written in red ink to distinguish them from amounts. Green ink is not the stated convention.'),
        ('acc11-03-sd-0024', 3, 'What code is used in a tax invoice for the classification of services under GST?', '1st July 2018', '1st July 2017', 'b', 1, 3, 'Recall the date GST was implemented in India.', 'GST was implemented in India on 1 July 2017. The date 1 July 2018 is one year later.'),
        ('acc11-03-sd-0025', 3, 'Which of the following items is outside the purview of GST according to the chapter note?', 'SAC (Service Accounting Code)', 'HSN (Harmonised System of Nomenclature)', 'a', 2, 3, 'Think about the code used to classify services.', 'SAC classifies services under GST. HSN is used for classifying goods.'),
        ('acc11-03-sd-0026', 3, 'According to the chapter''s GST schedule, which rate applies to LPG cylinders, tea, coffee, and railway transport services?', 'Low rated (5%)', 'Zero rated (0%)', 'b', 2, 3, 'Recall the GST treatment of essential food commodities.', 'The listed essential commodities fall under the zero-rated 0% slab in this classification. The low-rated slab is 5%.'),
        ('acc11-03-sd-0027', 3, 'Which GST rate applies to LPG cylinders, tea, coffee, and railway transport services?', '5% (Low rated)', '12% (Standard rated I slab)', 'a', 2, 3, 'Recall the slab for the listed everyday goods and services.', 'The listed items are assigned the 5% low-rated slab in this classification. The 12% slab is a different rate category.'),
        ('acc11-03-sd-0028', 3, 'Which of the following items is categorized under the 28% (Highly rated) GST slab?', '18% (Standard rated II slab)', '12% (Standard rated I slab)', 'b', 2, 3, 'Think about the GST slab for the listed consumer goods.', 'The listed consumer goods are placed in the 12% slab in this classification. The 18% slab is a different rate category.'),
        ('acc11-03-sd-0029', 3, 'When goods or services are purchased within a state with GST, how is the total tax split?', 'Luxury cars, air conditioners, and five-star hotel accommodation', 'Computers, printers, and courier services', 'a', 2, 3, 'Recall examples of highly rated goods and services.', 'Luxury cars, air conditioners, and five-star hotel accommodation are listed in the 28% slab. Computers, printers, and courier services are categorized in a lower slab.'),
        ('acc11-03-sd-0030', 3, 'When a business sells goods or services on which GST is levied, which tax accounts are credited in the seller''s books?', 'Equally divided into CGST (Central GST) and SGST (State GST)', '100% credited to CGST with no state component', 'a', 2, 3, 'Think about an intra-state taxable supply.', 'For an intra-state supply, GST is split between CGST and SGST. It is not assigned entirely to CGST.'),
        ('acc11-03-sd-0031', 3, 'When goods are purchased on credit from Mrs. Sonali for ₹15,000, what is the correct journal entry?', 'Output CGST A/c and Output SGST A/c', 'Input CGST A/c and Input SGST A/c', 'a', 1, 3, 'Think about the seller''s tax collected on sales.', 'A seller credits output tax accounts for GST charged on sales. Input tax accounts track GST paid on purchases.'),
        ('acc11-03-sd-0032', 3, 'Which of the following is NOT listed in the chapter as a valid reason for returning goods to a supplier?', 'Return Inward A/c (or Sales Return A/c)', 'Return Outward A/c (or Purchase Return A/c)', 'b', 2, 3, 'Think about returns made by a buyer to a supplier.', 'Goods returned to a supplier are recorded in Return Outward or Purchase Return. Return Inward or Sales Return records goods returned by customers.'),
        ('acc11-03-sd-0033', 3, 'How is a ''Bearer Cheque'' received from a debtor treated on the date of receipt, according to the chapter''s explanatory notes?', 'A simple entry involves only cash transactions, whereas a compound entry involves only credit transactions', 'A simple entry affects exactly two accounts (one debit, one credit), whereas a compound entry affects more than two accounts', 'b', 2, 3, 'Think about how many accounts are affected.', 'A simple entry affects two accounts, while a compound entry affects more than two. The distinction is not based on cash versus credit transactions.'),
        ('acc11-03-sd-0034', 3, 'Cash discount is granted by a seller to a buyer specifically to:', 'Trade Discount', 'Cash Discount', 'a', 1, 3, 'Think about the discount applied to the listed price before recording.', 'Trade discount reduces the list price and is not recorded separately in the books. Cash discount is recorded because it relates to prompt payment.'),
        ('acc11-03-sd-0035', 3, 'In the books of the person receiving cash, how is Cash Discount classified and recorded?', 'Encourage prompt payment', 'Promote bulk purchases of slow-moving inventory', 'a', 2, 3, 'Think about the reason for rewarding early settlement.', 'Cash discount encourages prompt payment. Discounts intended to promote bulk purchases are trade discounts.'),
        ('acc11-03-sd-0036', 3, 'Amar bought goods worth ₹20,000 from Rakesh at a 10% Trade Discount. At what value will the transaction be recorded in Amar''s Purchases A/c?', 'It is a loss (Nominal Account) and is debited to Discount Allowed A/c', 'It is a gain (Nominal Account) and is credited to Discount Received A/c', 'a', 2, 3, 'Think about the discount granted by the business receiving payment.', 'For the business receiving cash and granting the discount, cash discount is a loss debited to Discount Allowed A/c. Discount Received is a gain for the party that benefits from the discount.'),
        ('acc11-03-sd-0037', 3, 'The college fees of the proprietor''s son amounting to ₹1,000 are paid from the business cash box. What is the journal entry?', 'Computer A/c', 'Transport Charges A/c', 'a', 2, 3, 'Think about whether the transport cost helps acquire a fixed asset.', 'Transport charges for a newly purchased office computer are part of bringing the asset into use, so Computer A/c is debited. A separate transport expense account would not capitalize the acquisition cost.'),
        ('acc11-03-sd-0038', 3, 'When commission is paid to an agent, which account must be debited in the journal?', 'Machinery A/c', 'Wages A/c', 'a', 1, 3, 'Think about costs directly required to install a fixed asset.', 'Wages for installing machinery are part of the asset''s acquisition and installation cost, so Machinery A/c is debited. Ordinary wages are treated as an expense.'),
        ('acc11-03-sd-0039', 3, 'When a loan is taken from Dena Bank and credited to the business account, which account is credited?', 'Agent''s Personal A/c', 'Commission A/c', 'b', 2, 3, 'Identify the expense incurred when commission is paid.', 'Commission A/c is debited because commission paid is an expense. The agent''s personal account is not the expense account to debit.'),
        ('acc11-03-sd-0040', 3, 'When rent of a business premises is paid to landlord Mr. Sharma, which account is debited?', 'Dena Bank Current A/c', 'Dena Bank Loan A/c', 'b', 2, 3, 'Think about the liability created by borrowing money.', 'The loan account is credited because borrowing creates a liability. The bank current account is debited when the borrowed funds enter the business bank account.'),
        ('acc11-03-sd-0041', 3, 'If a proprietor withdraws cash or goods from the business, how does this affect proprietor''s capital?', 'Rent A/c', 'Landlord Mr. Sharma''s A/c', 'a', 1, 3, 'Identify the expense incurred for using business premises.', 'Rent A/c is debited as a business expense. The landlord''s personal account is not the expense account to debit.'),
        ('acc11-03-sd-0042', 3, 'When GST is paid on the purchase of goods, which tax account should be debited?', 'It decreases capital', 'It increases capital', 'a', 1, 3, 'Think about the effect of personal withdrawals on the owner''s equity.', 'Drawings reduce the proprietor''s capital. They do not increase it.'),
        ('acc11-03-sd-0043', 3, 'When income tax of the proprietor is paid by cheque from the business bank account, which account is debited?', 'Input Tax A/c (Input CGST / Input SGST)', 'Output Tax A/c (Output CGST / Output SGST)', 'a', 2, 3, 'Think about tax paid on purchases rather than tax collected on sales.', 'GST paid on purchases is recorded in Input Tax accounts. Output Tax accounts record GST charged on sales.'),
        ('acc11-03-sd-0044', 3, 'A proprietor transfers ₹50,000 from their personal Fixed Deposit account into the business Bank account. What is the credit aspect of this transaction?', 'Income Tax Expense A/c', 'Drawings A/c', 'b', 2, 3, 'Think about whether the proprietor''s personal tax is a business expense.', 'The proprietor''s personal income tax paid from business funds is treated as drawings. It is not a business income-tax expense.'),
        ('acc11-04-sd-0001', 4, 'How may a ledger be maintained in modern accounting systems compared with traditional bound books?', 'As separate cards or computer records', 'Solely as bank passbooks maintained by financial institutions', 'a', 1, 3, 'Consider electronic records and separate physical cards.', 'A ledger may be maintained as separate cards or computer records. Bank passbooks are not the only form of ledger maintenance.'),
        ('acc11-04-sd-0002', 4, 'Which practical limitation of the Journal does the Ledger specifically overcome?', 'The inability to verify source documents like vouchers and invoices', 'The inability to quickly ascertain total expenditure on a specific head or the net amount due to/from a party', 'b', 2, 3, 'Think about finding account-specific totals and balances quickly.', 'A ledger groups transactions by account, making expenditure under a particular head or the amount due from a party easier to find. Source documents still provide evidence for transactions.'),
        ('acc11-04-sd-0003', 4, 'What does the term ''Ledger Folio'' (L.F.) signify in accounting records?', 'The serial number of the journal entry in the day book', 'The page number of the ledger on which a particular account appears', 'b', 1, 3, 'This term identifies where an account appears in the ledger.', 'Ledger Folio (L.F.) is the page number where the account appears in the ledger. A journal-entry serial number is not a ledger folio.'),
        ('acc11-04-sd-0004', 4, 'How is the index of a physical Ledger prepared, and what information does it present?', 'In alphabetical order, showing the account name and its assigned page number for quick reference', 'In chronological order, showing transaction dates and amounts', 'a', 1, 3, 'Look for the usual ordering used to locate account names.', 'A ledger index is arranged alphabetically and gives each account''s page number. Chronological transaction dates and amounts are not the index''s organizing principle.'),
        ('acc11-04-sd-0005', 4, 'In manual ledger accounting, how do entries in the Particulars column conventionally begin on the Debit side and Credit side?', 'Debit side entries begin with ''By'', and Credit side entries begin with ''To''', 'Debit side entries begin with ''To'', and Credit side entries begin with ''By''', 'b', 1, 3, 'Recall the conventional words used on each side of a ledger.', 'Debit-side particulars conventionally begin with “To,” while credit-side particulars begin with “By.” The reverse arrangement is incorrect.'),
        ('acc11-04-sd-0006', 4, 'What is the specific purpose of the ''Journal Folio'' (J.F.) column in a ledger account?', 'To record the page number of the Journal from where the transaction has been transferred', 'To record the corresponding page number of the ledger where the counterpart account is opened', 'a', 1, 3, 'The abbreviation J.F. links a ledger entry to its source book.', 'The Journal Folio column records the journal page from which the transaction was transferred. A ledger page number belongs to the Ledger Folio column.'),
        ('acc11-04-sd-0007', 4, 'What is the precise definition of ''Posting'' in bookkeeping?', 'The process of transferring entries from the Journal or Subsidiary Books into the appropriate accounts in the Ledger', 'The process of entering initial transactions into the Journal from vouchers', 'a', 1, 3, 'Posting takes place after transactions have been recorded initially.', 'Posting transfers entries from the Journal or subsidiary books to the appropriate ledger accounts. Recording transactions initially in the Journal is journalizing, not posting.'),
        ('acc11-04-sd-0008', 4, 'When opening balances from a previous accounting period are recorded in an existing ledger account, how are they entered?', 'As ''To Balance c/d'' on the debit side or ''By Balance c/d'' on the credit side', 'As ''To Balance b/d'' on the debit side or ''By Balance b/d'' on the credit side', 'b', 1, 3, 'Opening balances use the abbreviation for balances brought forward.', 'An opening debit balance is entered as “To Balance b/d,” and an opening credit balance as “By Balance b/d.” “c/d” identifies the closing balance carried down.'),
        ('acc11-04-sd-0009', 4, 'Which GSTs apply to intra-state and inter-state purchases, respectively?', 'Intra-state: CGST and SGST; Inter-state: IGST', 'Intra-state: IGST; Inter-state: CGST and SGST', 'a', 1, 3, 'Recall the tax treatment based on whether a transaction crosses state borders.', 'Intra-state purchases attract CGST and SGST, while inter-state purchases attract IGST. IGST is not the usual combination for intra-state purchases.'),
        ('acc11-04-sd-0010', 4, 'Why does an enterprise that maintains a columnar Cash Book with Cash and Bank columns not maintain separate Cash and Bank accounts in the Ledger?', 'Because cash transactions do not follow double-entry rules', 'Because the Cash Book serves the function of both a book of original entry (Journal) and a book of final entry (Ledger)', 'b', 2, 3, 'Consider the two accounting functions performed by the Cash Book.', 'A Cash Book serves as both a book of original entry and a ledger for cash and bank accounts. Cash transactions still follow double-entry principles.'),
        ('acc11-04-sd-0011', 4, 'When the chief cashier hands over initial imprest cash to the petty cashier, which journal entry is recorded and posted?', 'Cash/Bank A/c Dr. To Petty Cash A/c', 'Petty Cash A/c Dr. To Cash/Bank A/c', 'b', 2, 3, 'The petty cashier receives cash from the main cashier.', 'When imprest cash is provided, Petty Cash Account is debited and Cash/Bank Account is credited. Reversing this entry records the movement in the wrong direction.'),
        ('acc11-04-sd-0012', 4, 'Which transactions are recorded in the Journal Proper?', 'Transactions not covered by special subsidiary books (e.g. opening entries, credit purchase of assets); posted individually to respective ledger accounts', 'Credit sales of merchandise goods; posted only to the Sales Account', 'a', 2, 3, 'Think of transactions that do not belong in a special subsidiary book.', 'Journal Proper records transactions not covered by special subsidiary books, such as opening entries and credit purchases of assets. Routine credit sales of goods belong in the Sales Book.'),
        ('acc11-04-sd-0013', 4, 'In ledger balancing, what does the abbreviation ''c/d'' indicate and represent?', 'Carried down, indicating the opening balance at the beginning of the period', 'Carried down, indicating the closing balance at the end of the period', 'b', 1, 3, 'This abbreviation marks the balance at the end of an accounting period.', '“c/d” means “carried down” and indicates the closing balance. The opening balance is brought down using “b/d.”'),
        ('acc11-04-sd-0014', 4, 'What does the abbreviation ''b/d'' stand for when opening an account at the start of a new period?', 'Brought down, representing the opening balance brought forward from the prior period', 'Brought down, representing the closing balancing figure', 'a', 1, 3, 'This abbreviation is used for the balance at the start of a period.', '“b/d” means “brought down” and represents the opening balance carried forward from the previous period. The closing balancing figure is marked “c/d.”'),
        ('acc11-04-sd-0015', 4, 'When is an account said to have a ''Debit balance''?', 'When the total of its credit side is greater than the total of its debit side', 'When the total of its debit side is greater than the total of its credit side', 'b', 1, 3, 'Compare the two sides'' totals.', 'An account has a debit balance when its debit-side total exceeds its credit-side total. If the credit total is greater, the account has a credit balance.'),
        ('acc11-04-sd-0016', 4, 'When does a ledger account show a ''Nil balance''?', 'When the total of the debit side is exactly equal to the total of the credit side', 'When no transactions have been entered during the entire financial year', 'a', 1, 3, 'A nil balance means there is no difference between the sides.', 'A ledger account has a nil balance when its debit and credit totals are equal. Having no transactions during the year is not required for a nil balance.'),
        ('acc11-04-sd-0017', 4, 'Which statement is true of Real Accounts such as Cash, Furniture, and Machinery?', 'Real Accounts always show a debit balance (or nil balance), never a credit balance', 'Real Accounts are closed at year-end by transfer to Profit and Loss Account', 'a', 1, 3, 'Real accounts relate to assets and property.', 'Real Accounts normally have a debit balance or a nil balance. They are not closed by transferring their balances to the Profit and Loss Account.'),
        ('acc11-04-sd-0018', 4, 'How are Nominal Accounts (expenses, losses, incomes, gains) treated at the close of an accounting year?', 'They are carried forward as assets or liabilities on the Balance Sheet', 'They are closed by transferring their balances to Trading Account or Profit and Loss Account', 'b', 2, 3, 'These accounts measure income, gains, expenses, and losses for a period.', 'Nominal Account balances are transferred to the Trading Account or Profit and Loss Account at year-end. They are not carried forward as assets or liabilities.'),
        ('acc11-04-sd-0019', 4, 'Why is the proprietor''s Capital Account treated as a liability of the business?', 'Due to the Business Entity Concept, which treats the business as a separate distinct legal entity from its owner', 'Because the Indian Partnership Act mandates treating capital as an external debt', 'a', 2, 3, 'Consider the Business Entity Concept.', 'The Business Entity Concept treats the business separately from its owner, so the capital contributed is regarded as an amount owed by the business to the proprietor. It is not an external debt mandated by partnership law.'),
        ('acc11-04-sd-0020', 4, 'What is the normal balance of the proprietor''s Drawings Account?', 'Credit balance; shown in the Credit Amount column', 'Debit balance; shown in the Debit Amount column', 'b', 1, 3, 'Drawings reduce the owner''s equity.', 'The Drawings Account normally has a debit balance because withdrawals reduce the proprietor''s equity. It does not normally have a credit balance.'),
        ('acc11-04-sd-0021', 4, 'What is a Trial Balance?', 'A summary register containing only real and personal accounts', 'An abstract or list of all ledger accounts as on a specific date showing debit and credit balances', 'b', 1, 3, 'It summarizes ledger balances on a particular date.', 'A Trial Balance is a list of ledger accounts showing their debit and credit balances on a specific date. It does not contain only real and personal accounts.'),
        ('acc11-04-sd-0022', 4, 'What is the primary reason or utility for preparing a Trial Balance periodically?', 'To ascertain the arithmetical accuracy of the Books of Accounts', 'To prove that no fraudulent transactions occurred during the year', 'a', 1, 3, 'It checks whether total debits and credits agree arithmetically.', 'A Trial Balance is prepared primarily to check the arithmetical accuracy of the books of account. It cannot prove that no fraud has occurred.'),
        ('acc11-04-sd-0023', 4, 'What are the two structural formats for preparing a Trial Balance?', 'Single Entry form and Double Entry form', 'Vertical (Journal form) and Horizontal (Ledger form)', 'b', 1, 3, 'One format resembles a Journal; the other resembles a Ledger.', 'The two formats are Vertical (Journal form) and Horizontal (Ledger form). Single Entry and Double Entry are accounting systems, not Trial Balance formats.'),
        ('acc11-04-sd-0024', 4, 'Which account normally carries a credit balance?', 'Outstanding Salary', 'Prepaid Rent', 'a', 2, 3, 'An unpaid expense is recorded as an amount owed.', 'Outstanding Salary is a liability and normally has a credit balance. Prepaid Rent is an asset and normally has a debit balance.'),
        ('acc11-05-sd-0001', 5, 'What is the primary difference between a Debit Note and a Credit Note in subsidiary book accounting?', 'A debit note is prepared by the buyer informing the seller of a debit; a credit note is prepared by the seller informing the buyer of a credit', 'Debit notes are used exclusively for cash purchases, while credit notes are used for credit purchases', 'a', 2, 3, 'Recall who prepares each note in a goods return.', 'The buyer prepares a debit note when returning goods; the seller issues a credit note to inform the buyer of the credit.'),
        ('acc11-05-sd-0002', 5, 'Which of the following errors is rectified through an entry in the Journal Proper?', 'Wrong totaling of the cash receipts column', 'Credit purchase of goods completely omitted from the books of accounts', 'b', 2, 3, 'Recall which errors require Journal Proper correction.', 'A complete omission of a credit purchase can be corrected through Journal Proper. Cash-book totaling errors are corrected in the cash book.'),
        ('acc11-05-sd-0003', 5, 'How does the Imprest System of Petty Cash Book operate?', 'The chief cashier surrenders full financial liability to the petty cashier permanently', 'The petty cashier is reimbursed at the end of the period with an amount exactly equal to actual expenses spent, restoring the original advance', 'b', 2, 3, 'Think about how the petty cash float is restored.', 'Under the imprest system, the petty cashier is reimbursed for actual expenses to restore the original float. The advance is not permanently transferred.'),
        ('acc11-05-sd-0004', 5, 'Which of the following is an operational advantage of maintaining Subsidiary Books that arises from assigning specialized staff to handle specific books?', 'Elimination of cash discount calculations', 'Increase in work efficiency through specialization', 'b', 1, 3, 'Think about assigning specialized accounting tasks.', 'Specialization improves work efficiency. It does not automatically remove discount calculations.'),
        ('acc11-05-sd-0005', 5, 'Which of the following describes an inter-state credit sale transaction of readymade garments subject to 5% GST?', 'CGST @ 2.5% and SGST @ 2.5% are charged', 'IGST @ 5% is charged on the taxable value', 'b', 2, 3, 'Recall the tax on an inter-state taxable sale.', 'An inter-state sale attracts IGST on the taxable value. CGST and SGST are generally used for intra-state supplies.'),
        ('acc11-05-sd-0006', 5, 'What does a credit balance in the Bank column of a two-column Cash Book indicate?', 'Unclaimed interest allowed by the bank', 'Bank Overdraft', 'b', 1, 3, 'Recall what a negative bank balance represents.', 'A credit balance in the Cash Book’s Bank column represents a bank overdraft, not surplus deposits.'),
        ('acc11-05-sd-0007', 5, 'Which bank account is primarily preferred by businessmen because it imposes no restrictions on deposits/withdrawals and provides an overdraft facility?', 'Current Account', 'Savings Bank Account', 'a', 1, 3, 'Think of the account used for frequent business transactions.', 'A Current Account supports frequent deposits and withdrawals and may provide an overdraft. Fixed and recurring deposits are designed for saving.'),
        ('acc11-05-sd-0008', 5, 'Which of the following transactions is strictly recorded in the Purchase Book (Bought Day Book)?', 'Purchase of office furniture on credit', 'Credit purchase of goods meant for resale or manufacturing', 'b', 1, 3, 'Recall what belongs in the Purchase Book.', 'The Purchase Book records credit purchases of goods for resale or manufacturing. Cash purchases are recorded in the Cash Book.'),
        ('acc11-05-sd-0009', 5, 'Which type of entry is passed in the Journal Proper at the beginning of a financial year to open asset and liability accounts?', 'Adjusting Entry', 'Opening Entry', 'b', 1, 3, 'Recall the entry that establishes opening balances.', 'An opening entry brings asset and liability balances into the new financial year. An adjusting entry updates balances for accruals and other adjustments.'),
        ('acc11-05-sd-0010', 5, 'Which document is prepared by an employee or petty cashier to support each small expense payment before recording it in the Petty Cash Book?', 'Petty Cash Voucher', 'Debit Note', 'a', 1, 3, 'Recall the supporting document for small cash expenses.', 'A Petty Cash Voucher supports a small expense payment before it is entered in the Petty Cash Book.'),
        ('acc11-05-sd-0011', 5, 'How is the periodic total of the Purchase Return Book posted to the Purchase Return Account in the Ledger?', 'Credit side as ''By Sundries as per Purchase Return Book''', 'Debit side as ''To Sundries as per Purchase Return Book''', 'a', 2, 3, 'Recall the normal balance of Purchase Return Account.', 'The Purchase Return Account is credited with the periodic total of the Purchase Return Book.'),
        ('acc11-05-sd-0012', 5, 'Within what validity period must a cheque be presented to the bank for collection from its date of drawing before it becomes worthless?', 'Six months', 'Three months', 'b', 1, 3, 'Recall the usual cheque validity period in India.', 'A cheque is generally valid for three months from its date of issue; six months is not the applicable period.'),
        ('acc11-05-sd-0013', 5, 'Why are adjusting entries passed in the Journal Proper at the end of the accounting period?', 'To update ledger accounts on an accrual basis so Final Accounts reflect accurate results', 'To record cash receipts that were forgotten by the cashier', 'a', 2, 3, 'Think about accrual accounting at period-end.', 'Adjusting entries update accounts so income and expenses are recognized in the proper period. They are not merely for forgotten cash receipts.'),
        ('acc11-05-sd-0014', 5, 'Why can the Cash column of a Cash Book never show a credit balance?', 'Because a person or business cannot pay out more cash than what is available in hand', 'Because cash transactions are exempt from the double entry system rules', 'a', 2, 3, 'Consider the physical limit of cash in hand.', 'A cash balance cannot be negative because a business cannot pay out more physical cash than it holds.'),
        ('acc11-05-sd-0015', 5, 'What is the alternative name for the Purchase Return Book?', 'Returns Outward Book', 'Returns Inward Book', 'a', 1, 3, 'Recall the alternative name for purchase returns.', 'The Purchase Return Book is also called the Returns Outward Book. Returns Inward refers to sales returns.'),
        ('acc11-05-sd-0016', 5, 'Why is the Cash Book described as serving a dual purpose in accounting?', 'It acts as both the Trial Balance and the Balance Sheet of the firm', 'It acts as both a Book of Original Entry (Journal) and a classified ledger account (Ledger)', 'b', 2, 3, 'Think of the Cash Book’s two accounting roles.', 'The Cash Book serves as both a book of original entry and a ledger account. It is not a Trial Balance.'),
        ('acc11-05-sd-0017', 5, 'Which of the following items requires an adjusting entry in the Journal Proper before final accounts can be accurately prepared?', 'Cash sales made during the regular course of business', 'Prepaid insurance and outstanding rent', 'b', 2, 3, 'Recall examples of period-end adjustments.', 'Prepaid insurance and outstanding rent require adjusting entries so expenses are recognized in the correct accounting period.'),
        ('acc11-05-sd-0018', 5, 'Which of the following accounts allows the account holder to deposit a fixed amount monthly up to a specified maturity period to earn higher interest than a savings account?', 'Recurring Deposit Account', 'Current Account', 'a', 1, 3, 'Think of a deposit made regularly each month.', 'A Recurring Deposit Account accepts fixed regular deposits until maturity. A Current Account is intended for frequent transactions.'),
        ('acc11-05-sd-0019', 5, 'A trader withdraws Rs. 12,000 from the bank for office use. What type of entry is this in a two-column Cash Book?', 'Opening entry', 'Contra entry', 'b', 2, 3, 'Think of transfers between cash and bank.', 'A transfer between cash and bank is a contra entry. An opening entry establishes opening balances.'),
        ('acc11-05-sd-0020', 5, 'In an Analytical Petty Cash Book, which special column is provided to record payments made towards Personal or Real accounts rather than nominal expense heads?', 'Ledger column', 'Miscellaneous Expenses column', 'a', 1, 3, 'Recall the column for non-expense ledger items.', 'The Ledger column records payments relating to personal or real accounts rather than named expense heads. Miscellaneous Expenses is for general expenses.'),
        ('acc11-05-sd-0021', 5, 'Which of the following transactions is entered in the Sales Book (Sales Journal)?', 'Cash sales of merchandise goods', 'Credit sale of merchandise goods dealt in by the firm', 'b', 1, 3, 'Think about the type of sale recorded in the Sales Book.', 'The Sales Book records credit sales of merchandise dealt in by the firm. Cash sales go in the Cash Book.'),
        ('acc11-05-sd-0022', 5, 'What is the primary source document prepared by the seller to record an entry in the Sales Book?', 'Inward Invoice', 'Outward Invoice', 'b', 1, 3, 'Recall the invoice prepared by the seller.', 'The seller’s outward invoice is the source document for recording a credit sale in the Sales Book.'),
        ('acc11-05-sd-0023', 5, 'When goods are purchased from an out-of-state supplier (inter-state purchase), which tax component is recorded in the analytical Purchase Book?', 'CGST and SGST in equal halves', 'Integrated GST (IGST)', 'b', 2, 3, 'Recall the tax applied to inter-state purchases.', 'Inter-state purchases generally attract IGST. CGST and SGST are typically applied to intra-state supplies.'),
        ('acc11-05-sd-0024', 5, 'The word ''Petty'' in Petty Cash Book is derived from which French word and what does it mean?', '''Petite'' meaning ''fast''', '''Petit'' meaning ''small''', 'b', 1, 3, 'Recall the French origin of “petty.”', '“Petit” is French for “small,” which describes the small-value payments recorded in a Petty Cash Book.'),
        ('acc11-05-sd-0025', 5, 'What is the alternative accounting name for the Sales Return Book?', 'Returns Outward Book', 'Returns Inward Book', 'b', 1, 3, 'Recall the alternative name for sales returns.', 'The Sales Return Book is also called the Returns Inward Book. Returns Outward refers to purchase returns.'),
        ('acc11-05-sd-0026', 5, 'Which letter is written in the Ledger Folio (L.F.) column of the Cash Book to signify a Contra Entry?', 'C', 'R', 'a', 1, 3, 'Recall the abbreviation used for contra entries.', 'The letter C marks a contra entry in the Ledger Folio column; R is not the standard mark.'),
        ('acc11-05-sd-0027', 5, 'At what monetary value are credit purchases always recorded in the Purchase Book?', 'Net value after deducting trade discount', 'Gross catalogue price before deducting trade discount', 'a', 1, 3, 'Think about the effect of trade discount.', 'Credit purchases are entered at the net invoice value after trade discount, not the gross catalogue price.'),
        ('acc11-05-sd-0028', 5, 'On which side and in which column is a cash receipt recorded in a Simple Cash Book?', 'Debit side (Receipt side) in the Amount column', 'Credit side (Payment side) in the Amount column', 'a', 1, 3, 'Recall where cash receipts are entered.', 'Cash receipts are recorded on the debit (receipt) side in the Amount column. The payment side records cash outflows.'),
        ('acc11-05-sd-0029', 5, 'What happens when an analytical petty cash book contains a column for ''Ledger Accounts''?', 'Amounts in that column are posted individually to personal or real accounts in the ledger', 'It is totaled and posted to the Trading Account at the end of the year', 'a', 2, 3, 'Think about where ledger-related amounts are posted.', 'Amounts in the Ledger Accounts column are posted individually to the relevant personal or real ledger accounts. It does not replace the main Cash Book.'),
        ('acc11-05-sd-0030', 5, 'How is the periodic total of the Sales Return Book posted to the Sales Return Account in the Ledger?', 'Debit side as ''To Sundries as per Sales Return Book''', 'Credit side as ''By Sundries as per Sales Return Book''', 'a', 2, 3, 'Recall the normal balance of Sales Return Account.', 'The Sales Return Account is debited with the periodic total because sales returns reduce sales revenue.'),
        ('acc11-05-sd-0031', 5, 'What source document is prepared by the buyer and sent to the supplier when returning defective goods?', 'Debit Note', 'Credit Note', 'a', 1, 3, 'Recall the document sent by a buyer returning goods.', 'A buyer sends a debit note to the supplier when returning goods. A credit note is generally issued by the seller.'),
        ('acc11-05-sd-0032', 5, 'What is the primary reason for sub-dividing the Journal into Special Journals as a business expands?', 'To eliminate the need for posting transactions into the Ledger', 'The volume of transactions becomes too large to be recorded in a single Journal', 'b', 1, 3, 'Recall why accounting records are divided.', 'Special Journals divide a large transaction volume into manageable records. They do not eliminate ledger posting.'),
        ('acc11-05-sd-0033', 5, 'In which book of original entry is a transaction recorded when goods are purchased on credit from a supplier and trade discount is allowed?', 'Cash Book at full list price', 'Purchase Book at net invoice price', 'b', 1, 3, 'Recall the book for credit purchases of trading goods.', 'Credit purchases of trading goods are recorded in the Purchase Book at net invoice price after trade discount.'),
        ('acc11-05-sd-0034', 5, 'Which account is debited in the Journal Proper when further bad debts of Rs. 3,750 are written off?', 'Debtors Account', 'Bad Debts Account', 'b', 1, 3, 'Recall the expense recorded when debts become irrecoverable.', 'Bad Debts Account is debited when further bad debts are written off. Debtors Account is credited.'),
        ('acc11-05-sd-0035', 5, 'Which of the following statements is TRUE regarding Trade Discount and Cash Discount?', 'Trade discount is recorded in the Cash Book, while Cash discount is deducted from the invoice', 'Trade discount is deducted on the invoice and not recorded separately; Cash discount is allowed for prompt payment and recorded in the books', 'b', 2, 3, 'Recall when trade and cash discounts are recorded.', 'Trade discount is deducted from the invoice and not separately recorded; cash discount for prompt payment is recorded in the books.'),
        ('acc11-05-sd-0036', 5, 'What is the monthly summary journal entry passed in the principal journal to post the expenses recorded in the Analytical Petty Cash Book?', 'Respective Expense Accounts Dr. To Bank A/c', 'Respective Expense Accounts Dr. To Petty Cash A/c', 'b', 2, 3, 'Think about the accounting entry for petty expenses.', 'The expense accounts are debited and Petty Cash is credited when posting petty expenses. The bank account is not credited for every petty expense.'),
        ('acc11-05-sd-0037', 5, 'How does maintaining Subsidiary Books facilitate the internal check system within an organization?', 'It removes the need for physical verification of cash and stock balances', 'Verification of the correctness of accounting records can be made more effectively', 'b', 2, 3, 'Consider how divided duties support verification.', 'Subsidiary Books make checking accounting records more effective. They cannot eliminate the need to verify cash or stock.'),
        ('acc11-05-sd-0038', 5, 'Which source document is issued by the seller to a customer upon receiving defective goods returned by that customer?', 'Debit Note', 'Credit Note', 'b', 1, 3, 'Recall what the seller issues for returned goods.', 'A seller issues a credit note to acknowledge goods returned by a customer. A debit note is normally prepared by the buyer.'),
        ('acc11-05-sd-0039', 5, 'Which subsidiary book is used to record transactions relating to bills received from debtors when bill transactions are segregated?', 'Bills Receivable Book', 'Bills Payable Book', 'a', 1, 3, 'Recall the book used for bills received.', 'The Bills Receivable Book records bills received from debtors. The Bills Payable Book records bills accepted or payable.'),
        ('acc11-05-sd-0040', 5, 'Why are Subsidiary Books also referred to as ''Books of Original Entry'' or ''Books of Prime Entry''?', 'Transactions are first recorded in these books before being posted to the Ledger', 'They are prepared directly from the Final Accounts at the end of the year', 'a', 1, 3, 'Consider when transactions are first recorded.', 'Subsidiary Books are books of original entry because transactions are recorded in them before ledger posting. Final accounts are prepared later.'),
        ('acc11-05-sd-0041', 5, 'What is the primary source document used for recording entries in the Purchase Book?', 'Inward Invoice', 'Outward Invoice', 'a', 1, 3, 'Recall the invoice received from a supplier.', 'An inward invoice from the supplier is the source document for the Purchase Book. An outward invoice is issued by the seller.'),
        ('acc11-05-sd-0042', 5, 'When a trader receives a Credit Note from a supplier for goods previously returned, in which book does the trader record this return?', 'Purchase Return Book', 'Sales Return Book', 'a', 2, 3, 'Recall the book used for goods returned to a supplier.', 'A buyer records goods returned to a supplier in the Purchase Return Book, not the Sales Return Book.'),
        ('acc11-05-sd-0043', 5, 'How is the periodic total of the Sales Book posted to the Sales Account in the Ledger?', 'Credit side as ''By Sundries as per Sales Book''', 'Debit side as ''To Sundries as per Sales Book''', 'a', 2, 3, 'Recall the normal balance of Sales Account.', 'The Sales Book total is posted to the credit side of Sales Account because sales are revenue.'),
        ('acc11-05-sd-0044', 5, 'How is the periodic total of the Purchase Book posted to the Purchases Account in the Ledger?', 'Debit side as ''To Sundries as per Purchase Book''', 'Credit side as ''By Sundries as per Purchase Book''', 'a', 2, 3, 'Recall the normal balance of the Purchases Account.', 'The Purchase Book total is posted to the debit side of Purchases Account. Individual suppliers’ accounts are credited.'),
        ('acc11-05-sd-0045', 5, 'Goods costing Rs. 11,000 distributed as free samples to promote sales are recorded in the Journal Proper by debiting which account?', 'Advertisement Account', 'Sales Account', 'a', 1, 3, 'Think about the purpose of giving free samples.', 'Free samples are a sales-promotion cost, so Advertisement Account is debited. Drawings applies to goods taken for personal use.'),
        ('acc11-05-sd-0046', 5, 'What is the primary function of the Journal Proper?', 'To record all cash transactions not recorded by the petty cashier', 'To record transactions that do not find a place in any special subsidiary books', 'b', 1, 3, 'Think about transactions not covered by special books.', 'Journal Proper records transactions that do not fit in other subsidiary books. It is not used only for banking transactions.'),
        ('acc11-05-sd-0047', 5, 'In a two-column Cash Book, what does the balance brought down on the receipt side in the Cash column represent?', 'Cash in hand available at the beginning of the period', 'Bank Overdraft at the beginning of the period', 'a', 1, 3, 'Think about the opening cash balance.', 'A balance brought down on the receipt side of the Cash column represents cash in hand at the start of the period.'),
        ('acc11-06-sd-0001', 6, 'What basic facts of a financial transaction are specifically described by an accounting document?', 'Amount, recipient, purpose, and date of transaction', 'Future market value, inflation rate, and vendor profit margin', 'a', 1, 3, 'Accounting documents record key transaction details.', 'Accounting documents record details such as amount, recipient, purpose, and date; they do not describe depreciation estimates.'),
        ('acc11-06-sd-0002', 6, 'What primary evidentiary role do accounting documents play in the process of Book-Keeping?', 'They eliminate the requirement to maintain a journal or ledger', 'They provide evidence that a financial transaction has actually taken place', 'b', 1, 3, 'Accounting documents provide evidence of transactions.', 'They provide evidence that a financial transaction occurred; they do not eliminate the need for journals or ledgers.'),
        ('acc11-06-sd-0003', 6, 'Which modern banking method provides instant and automatic proof of payment and receipt for both parties without requiring a physical visit to the bank?', 'Manual withdrawal slip', 'Internet and mobile banking', 'b', 1, 3, 'Digital banking can provide immediate transaction proof.', 'Internet and mobile banking provide instant electronic proof without a branch visit; a manual withdrawal slip requires a physical process.'),
        ('acc11-06-sd-0004', 6, 'What is another commonly used name for a Pay-in-slip?', 'Withdrawal slip', 'Deposit slip', 'b', 1, 3, 'A pay-in-slip is used when depositing money.', 'A pay-in-slip is also called a deposit slip; a withdrawal slip is used to take money out.'),
        ('acc11-06-sd-0005', 6, 'A Pay-in-slip is divided into two parts. Which part is stamped, signed, dated by the receiving clerk, and returned to the customer as an acknowledgement?', 'The left-hand side counterfoil', 'The right-hand side portion', 'a', 1, 3, 'The counterfoil serves as the depositor''s acknowledgement.', 'The left-hand counterfoil is stamped and returned as acknowledgement; the right-hand portion is retained by the bank.'),
        ('acc11-06-sd-0006', 6, 'How can a customer deposit a cheque along with a pay-in-slip in modern branches without waiting at the teller counter?', 'By submitting an online RTGS application form', 'By dropping it into the designated drop box placed in the bank', 'b', 1, 3, 'Cheque drop boxes allow deposits without teller service.', 'A designated bank drop box accepts cheques with pay-in-slips; an ATM withdrawal form is not used for this.'),
        ('acc11-06-sd-0007', 6, 'What is the specific term used in the chapter for availing banking services through extensive use of information technology without physically walking into bank premises?', 'Branch clearing banking', 'Virtual banking', 'b', 1, 3, 'Virtual banking uses information technology for remote services.', 'Virtual banking provides banking services through information technology without visiting a branch; branch clearing is not this concept.'),
        ('acc11-06-sd-0008', 6, 'What is a Bank Pass Book fundamentally defined as?', 'A duplicate of the cash column of the business Cash Book', 'A copy or extract of the ledger account of the account holder appearing in the books of the bank', 'b', 1, 3, 'A Pass Book records the account holder''s bank transactions.', 'A Pass Book is a copy or extract of the account holder''s ledger in the bank''s books; it is not the business''s Cash Book.'),
        ('acc11-06-sd-0009', 6, 'What direct operational and financial benefit does viewing, downloading, and printing electronic bank statements offer to banks and account holders?', 'It reduces the cost of paper and postage', 'It prevents cheques from being dishonoured', 'a', 1, 3, 'Electronic statements reduce paper and postage costs.', 'Viewing and printing electronic statements reduces paper and postage expenses; it does not prevent cheque dishonour.'),
        ('acc11-06-sd-0010', 6, 'What is a ''Bank Advice''?', 'A letter sent by the bank to an account holder in a prescribed form to inform them of debits/credits like dishonour, bank charges, or standing order payments', 'A letter sent by a customer requesting the bank to increase overdraft limits', 'a', 1, 3, 'Bank advice communicates account information to customers.', 'A bank advice is a prescribed-form letter informing an account holder about an account transaction; a loan sanction letter concerns loan terms.'),
        ('acc11-06-sd-0011', 6, 'Which contemporary technology has largely overtaken the role of physical Bank Advices for updating account holders?', 'SMS alerts and notifications on registered mobile numbers', 'Telegram dispatches', 'a', 1, 3, 'Banks commonly use registered-mobile alerts for updates.', 'SMS alerts and mobile notifications have largely replaced physical bank advices; telegrams are an outdated method.'),
        ('acc11-06-sd-0012', 6, 'Which electronic funds transfer system is available 24/7 throughout the year, including bank holidays, for immediate fund transfers?', 'Cheque Clearing House', 'Immediate Payment Service (IMPS)', 'b', 1, 3, 'IMPS supports immediate electronic fund transfers.', 'IMPS is available around the clock, including bank holidays; a demand draft is a physical payment instrument.'),
        ('acc11-06-sd-0013', 6, 'In a business ledger, what does the bank column of the Cash Book represent?', 'The capital account contributed by partners', 'The bank current account maintained by the businessman', 'b', 1, 3, 'The Cash Book''s bank column tracks the business bank account.', 'The bank column represents the businessperson''s bank current account; physical cash is recorded separately.'),
        ('acc11-06-sd-0014', 6, 'When a businessman deposits money or cheques into the bank, how is the entry recorded in the Cash Book and Pass Book respectively?', 'Debit side of Cash Book and Debit side of Pass Book', 'Debit side of Cash Book (Receipt) and Credit side of Pass Book (Receipt)', 'b', 2, 3, 'Deposits are receipts in the Cash Book and credits in the Pass Book.', 'A deposit is debited as a receipt in the Cash Book and credited by the bank in the Pass Book; it is not recorded as a payment in both.'),
        ('acc11-06-sd-0015', 6, 'When a businessman issues a cheque to pay a supplier, on which side of the Cash Book and Pass Book is the transaction entered?', 'Credit side of Cash Book (Payment) and Debit side of Pass Book (Payment)', 'Debit side of Cash Book and Debit side of Pass Book', 'a', 2, 3, 'Cheque payments are recorded as payments in the Cash Book.', 'A cheque issued is entered on the Cash Book''s credit/payment side and debited by the bank in the Pass Book; it is not entered on the Cash Book''s debit side.'),
        ('acc11-06-sd-0016', 6, 'Who is responsible for preparing the Bank Reconciliation Statement?', 'The commercial bank holding the account', 'The businessman / account holder', 'b', 1, 3, 'The account holder prepares the Bank Reconciliation Statement.', 'The businessman or account holder prepares the BRS; the bank does not prepare it for the business.'),
        ('acc11-06-sd-0017', 6, 'What are the two major broad categories of reasons causing differences between Cash Book balance and Pass Book balance?', 'Capital expenditures, and revenue expenditures', 'Time difference, and Errors and omissions made by bank or businessman', 'b', 1, 3, 'BRS differences arise from timing and errors or omissions.', 'The main causes are timing differences and errors or omissions by the bank or account holder, not capital and revenue expenditure categories.'),
        ('acc11-06-sd-0018', 6, 'When a cheque is issued to a creditor but has NOT yet been presented to the bank for payment by the reconciliation date, what is the comparative effect on the two books?', 'Cash Book balance will be higher than the balance as per Pass Book', 'Pass Book balance will be higher than the balance as per Cash Book', 'b', 2, 3, 'An unpresented cheque has not yet reduced the Pass Book balance.', 'The Cash Book records the cheque when issued, while the Pass Book changes when it is presented; therefore, the Pass Book balance is higher.'),
        ('acc11-06-sd-0019', 6, 'When cheques are deposited into the bank but not yet cleared and collected by the bank, what is the relative state of the two balances?', 'Pass Book balance is higher than Cash Book balance', 'Cash Book balance is higher than Pass Book balance', 'b', 2, 3, 'Uncleared deposits appear in the Cash Book before the Pass Book.', 'The Cash Book records the deposit immediately, while the bank has not yet credited it, so the Cash Book balance is higher.'),
        ('acc11-06-sd-0020', 6, 'When the bank credits interest on deposit in the Pass Book, what is the effect on the balances before the customer receives intimation?', 'Pass Book balance is higher than Cash Book balance', 'Cash Book balance is higher than Pass Book balance', 'a', 2, 3, 'Bank interest may appear before the Cash Book is updated.', 'The bank credits interest in the Pass Book first, so that balance is higher until the Cash Book is updated.'),
        ('acc11-06-sd-0021', 6, 'When the bank pays insurance premiums, electricity bills, or loan instalments under standing instructions, what is the effect on relative balances before intimation?', 'Pass Book balance will be less than Cash Book balance', 'Cash Book balance will decrease automatically without any intimation', 'a', 2, 3, 'Standing instructions can cause payments before the Cash Book is updated.', 'The bank debits the account for these payments before the customer records them, making the Pass Book balance lower.'),
        ('acc11-06-sd-0022', 6, 'How do bank charges, commission, and interest on overdraft debited by the bank affect the Pass Book balance on the reconciliation date?', 'They cause Pass Book balance to be less than Cash Book balance', 'They have no effect on either book balance', 'a', 2, 3, 'Bank charges reduce the Pass Book balance.', 'Charges and overdraft interest debited by the bank reduce the Pass Book balance; they do affect the account balance.'),
        ('acc11-06-sd-0023', 6, 'When a customer''s debtor deposits money directly into the businessman''s bank account via NEFT or cash, what is the effect on the two books before the bank statement is received?', 'Balance shown in Cash Book will be more than balance shown in Pass Book', 'Balance shown in Pass Book will be more than balance shown in Cash Book', 'b', 2, 3, 'Direct customer deposits may appear in the Pass Book first.', 'The bank records the direct deposit before the business updates its Cash Book, so the Pass Book balance is higher.'),
        ('acc11-06-sd-0024', 6, 'When a bill of exchange discounted with the bank is dishonoured on the due date, what entry does the bank make in the Pass Book?', 'Bank debits the customer''s account in the Pass Book', 'Bank credits the customer''s account to return the discount charge', 'a', 2, 3, 'A dishonoured discounted bill is charged back to the customer.', 'When a discounted bill is dishonoured, the bank debits the customer''s account in the Pass Book; it does not credit the account.'),
        ('acc11-06-sd-0025', 6, 'If a cheque issued by a businessman to make a payment is returned dishonoured, how does the bank cancel the earlier debit entry in the Pass Book?', 'Bank credits the customer''s account in the Pass Book', 'Bank debits the customer''s account a second time', 'a', 2, 3, 'A dishonoured cheque reverses the earlier bank payment entry.', 'The bank credits the customer''s account to reverse the earlier debit; it does not debit the account a second time.'),
        ('acc11-06-sd-0026', 6, 'Why is the last day of the month generally selected for preparing a Bank Reconciliation Statement?', 'Because Cash Book balance and Pass Book balance are readily available on that date', 'Because commercial banks close all business current accounts on that day', 'a', 1, 3, 'Month-end balances are usually available for reconciliation.', 'The last day of the month is convenient because both balances are readily available; banking laws do not prohibit mid-month reconciliation.'),
        ('acc11-06-sd-0027', 6, 'In accounting, what is the excess of bank deposits over withdrawals called?', 'Bank Overdraft', 'Bank Balance (Favourable Balance)', 'b', 1, 3, 'A positive bank balance means deposits exceed withdrawals.', 'The term is a favourable bank balance; a bank overdraft occurs when withdrawals exceed available funds.'),
        ('acc11-06-sd-0028', 6, 'What happens when an entry is debited in the Cash Book?', 'It increases the cash/bank balance', 'It decreases the cash/bank balance', 'a', 1, 3, 'Debits in the Cash Book generally record receipts.', 'A debit entry increases the cash or bank balance because the Cash Book is an asset account; it does not decrease the balance.'),
        ('acc11-06-sd-0029', 6, 'Which type of bank account holder is granted the ''Bank Overdraft'' facility by commercial banks?', 'Savings account holder', 'Current account holder', 'b', 1, 3, 'Overdraft facilities are commonly associated with current accounts.', 'Commercial banks generally grant overdraft facilities to current account holders, not standard savings account holders.'),
        ('acc11-06-sd-0030', 6, 'Payments credited in the Cash Book are recorded on which side of the Bank Pass Book?', 'Credited in Pass Book', 'Debited in Pass Book', 'b', 1, 3, 'Bank payments are debits in the Pass Book.', 'A payment recorded on the Cash Book''s credit side is a withdrawal from the bank, so the bank debits the customer''s account.'),
        ('acc11-06-sd-0031', 6, 'While preparing a Bank Reconciliation Statement, which specific column of the Cash Book is considered?', 'Bank column only', 'Cash column only', 'a', 1, 3, 'BRS compares the bank records in both books.', 'Only the bank column of the Cash Book is used for BRS; the cash column is excluded.'),
        ('acc11-06-sd-0032', 6, 'When a cheque is issued to a creditor, in which book does the entry appear FIRST?', 'Cash Book', 'Pass Book', 'a', 1, 3, 'The business records a cheque when it issues it.', 'The cheque is first entered in the Cash Book when issued; it appears in the Pass Book after bank processing.'),
        ('acc11-06-sd-0033', 6, 'Interest on overdraft charged by the bank is entered on which side of the Bank Pass Book?', 'Debited in Pass Book', 'Credited in Pass Book', 'a', 1, 3, 'Overdraft interest is a charge against the account holder.', 'The bank debits overdraft interest in the Pass Book because it is a charge; it is not credited.'),
        ('acc11-07-sd-0001', 7, 'Why does a business concern acquire fixed assets for its trading activities?', 'For permanent use in the business and not for resale', 'With the intention of immediate resale at profit', 'a', 1, 3, 'Fixed assets support ongoing business operations.', 'Fixed assets are acquired for continuing business use, not resale. Immediate resale describes trading stock.'),
        ('acc11-07-sd-0002', 7, 'The purchase of a fixed asset represents which type of expenditure?', 'Recurring revenue expenditure', 'Capital expenditure', 'b', 1, 3, 'Consider whether the purchase creates a long-term asset.', 'Buying a fixed asset is capital expenditure because it provides longer-term business use. Revenue expenditure relates to routine operating costs.'),
        ('acc11-07-sd-0003', 7, 'What is the accounting process of spreading the cost of fixed assets over their useful life termed as?', 'Amortisation of capital', 'Depreciation', 'b', 1, 3, 'Think of allocating an asset’s cost over its useful life.', 'Depreciation allocates a fixed asset’s cost over its useful life. Revaluation changes an asset’s recorded value rather than allocating its cost over time.'),
        ('acc11-07-sd-0004', 7, 'Which of the following fixed assets is never depreciated because its area neither increases nor decreases and its value often appreciates?', 'Building', 'Land', 'b', 1, 3, 'This natural property generally does not wear out through use.', 'Land is generally not depreciated because its useful life is usually indefinite. Buildings and machinery typically have limited useful lives.'),
        ('acc11-07-sd-0005', 7, 'Under accounting principles, when must depreciation be charged by a business concern?', 'Only when the firm generates sufficient net profit', 'Every year whether the business earns a profit or suffers a loss', 'b', 1, 3, 'Depreciation is an annual accounting charge.', 'Depreciation is charged each year, even when the business makes a loss. It is not conditional on earning sufficient profit.'),
        ('acc11-07-sd-0006', 7, 'Who defined depreciation as ''the gradual decrease in the value of an asset from any cause''?', 'R.N. Carter', 'R.G. Williams', 'a', 1, 3, 'Recall the accounting author associated with this definition.', 'William Pickles gave the quoted definition of depreciation. R.G. Williams is associated with a different definition.'),
        ('acc11-07-sd-0007', 7, 'Which cause of depreciation describes the physical deterioration resulting directly from actual operation or constant usage?', 'Obsolescence', 'Normal and Natural Wear and Tear', 'b', 1, 3, 'This cause results from an asset’s regular physical use.', 'Normal wear and tear is physical deterioration caused by use. Obsolescence results from becoming outdated rather than ordinary operation.'),
        ('acc11-07-sd-0008', 7, 'Certain assets like Patents, Trademarks, Copyrights, and Leases lose value even if they are not put to active use. What is this cause called?', 'Passage of Time (Effluxion of Time)', 'Depletion', 'a', 2, 3, 'Some rights lose value as their term passes.', 'Effluxion of time means value is lost as time passes, even without active use. Depletion results from extracting natural resources.'),
        ('acc11-07-sd-0009', 7, 'When an existing asset becomes out-dated due to technological development or improved production techniques, the cause of its value reduction is known as:', 'Impairment', 'Obsolescence', 'b', 1, 3, 'New technology can make existing equipment outdated.', 'Obsolescence occurs when technology or methods make an asset outdated. Impairment is a broader reduction in recoverable value.'),
        ('acc11-07-sd-0010', 7, 'What term refers to the reduction in value of wasting assets such as mines, quarries, oil-wells, and forests due to continuous extraction?', 'Obsolescence', 'Depletion', 'b', 1, 3, 'Extraction reduces the value of natural resources.', 'Depletion is the loss of value as resources such as minerals or oil are extracted. Wear and tear refers to physical deterioration through use.'),
        ('acc11-07-sd-0011', 7, 'Sudden damage to or loss of fixed assets caused by earthquakes, floods, fire, or cyclones is accounted for under:', 'Depletion of wasting assets', 'Natural Calamities / Impairment of an Asset', 'b', 1, 3, 'Consider damage caused by major natural events.', 'Natural calamities can cause sudden damage or loss of an asset. Depletion concerns the extraction of wasting resources.'),
        ('acc11-07-sd-0012', 7, 'When the market value of an asset falls below its cost due to prevailing economic conditions, it leads to depreciation through which factor?', 'Market Value changes', 'Physical obsolescence', 'a', 1, 3, 'Economic conditions can affect an asset’s market value.', 'Changes in market value can reduce an asset’s value under prevailing economic conditions. Legal expiration concerns the ending of a right or term.'),
        ('acc11-07-sd-0013', 7, 'In Book-Keeping, Depreciation Account is classified as which type of account?', 'Nominal Account', 'Real Account', 'a', 1, 3, 'Classify expenses and losses under traditional account types.', 'Depreciation Account is a nominal account because it records an expense. A real account generally records assets.'),
        ('acc11-07-sd-0014', 7, 'Why is depreciation termed a ''non-cash expenditure''?', 'It is paid exclusively via promissory notes', 'It involves an internal accounting write-off without an immediate outflow of cash', 'b', 2, 3, 'Consider whether depreciation itself requires a cash payment.', 'Depreciation is a non-cash expense because recording it does not itself pay out cash. Promissory notes are a payment instrument, not the nature of depreciation.'),
        ('acc11-07-sd-0015', 7, 'How does charging depreciation help a business in its dealings with the Government?', 'It eliminates the requirement of filing annual tax returns', 'It enables the business to compute and pay the correct amount of tax', 'b', 1, 3, 'Depreciation helps determine taxable business profit.', 'Depreciation helps calculate taxable profit and the correct tax due. It does not automatically exempt a business from filing returns.'),
        ('acc11-07-sd-0016', 7, 'The Straight Line Method of depreciation is also known as:', 'Fixed Instalment Method or Original Cost Method', 'Reducing Balance Method or Annuity Method', 'a', 1, 3, 'This method charges a consistent amount each year.', 'The Straight Line Method is also called the Fixed Instalment or Original Cost Method. The Reducing Balance Method calculates depreciation on the changing book value.'),
        ('acc11-07-sd-0017', 7, 'Under the Written Down Value Method, depreciation is calculated each year on:', 'The balance / book value brought forward on the opening date of each year', 'The original cost of the asset throughout its life', 'a', 1, 3, 'WDV uses the asset’s current carrying amount.', 'The Written Down Value method applies depreciation to the opening book value. Original cost remains the base under the Straight Line Method.'),
        ('acc11-07-sd-0018', 7, 'How does the annual depreciation charge behave over the life of an asset under the Written Down Value Method?', 'It goes on decreasing gradually each year', 'It remains constant every year', 'a', 1, 3, 'The depreciation base gets smaller over time.', 'WDV depreciation usually decreases as the opening book value falls. A constant charge is characteristic of the Straight Line Method.'),
        ('acc11-07-sd-0019', 7, 'Which depreciation method is recognized by Tax Authorities and Law?', 'Written Down Value Method', 'Fixed Instalment Method', 'a', 1, 3, 'Consider the method commonly accepted for tax purposes.', 'The Written Down Value Method is recognized for tax and legal purposes in this syllabus context. The Fixed Instalment Method is not the method identified for that recognition.'),
        ('acc11-07-sd-0020', 7, 'When wages or incidental expenses are paid to erect and install a new machine, which account is debited?', 'Installation Expenses Account', 'Machinery Account (Asset Account)', 'b', 2, 3, 'Installation costs form part of the asset’s cost.', 'Machinery Account is debited because installation costs are capitalized into the machine’s cost. Wages Account is not debited separately for these capital costs.'),
        ('acc11-07-sd-0021', 7, 'What is the correct journal entry to record annual depreciation charged on a fixed asset?', 'Debit Asset A/c; Credit Depreciation A/c', 'Debit Depreciation A/c; Credit Asset A/c', 'b', 1, 3, 'Depreciation is an expense and reduces the asset’s value.', 'Depreciation A/c is debited as an expense and Asset A/c is credited to reduce its book value. Reversing the entry would increase the asset and reduce the expense.'),
        ('acc11-07-sd-0022', 7, 'At the end of the accounting year, the balance of Depreciation Account is transferred by which journal entry?', 'Debit Profit and Loss A/c; Credit Depreciation A/c', 'Debit Asset A/c; Credit Profit and Loss A/c', 'a', 1, 3, 'Year-end expenses are closed to the profit and loss account.', 'Profit and Loss A/c is debited and Depreciation A/c is credited to close the expense. Crediting Profit and Loss would reverse the normal transfer.'),
        ('acc11-07-sd-0023', 7, 'When a fixed asset is purchased on credit from a vendor, the journal entry is:', 'Debit Asset A/c; Credit Supplier''s/Party''s A/c', 'Debit Purchases A/c; Credit Supplier''s A/c', 'a', 1, 3, 'A credit purchase increases an asset and a payable.', 'The asset account is debited and the supplier’s account is credited for a credit purchase. Purchases A/c is used for goods bought for resale, not a fixed asset.'),
        ('acc11-07-sd-0024', 7, 'When an asset is sold exactly at its Written Down Value (Book Value), the credit entry is made to:', 'Sales A/c', 'Asset A/c', 'b', 1, 3, 'The asset account is removed when the asset is sold.', 'Asset A/c is credited to remove the asset at its book value. Sales A/c is not the account credited for the disposal of a fixed asset itself.'),
        ('acc11-07-sd-0025', 7, 'When a fixed asset is sold for an amount exceeding its Written Down Value, which account is credited for the gain?', 'Profit on Sale of Asset A/c', 'Loss on Sale of Asset A/c', 'a', 2, 3, 'A sale above book value creates a gain.', 'Profit on Sale of Asset A/c is credited when selling proceeds exceed book value. Loss on Sale records a shortfall, not a gain.'),
        ('acc11-07-sd-0026', 7, 'When an asset is sold at a loss, the deficiency (WDV minus selling price) is debited to:', 'Loss on Sale of Asset A/c', 'Depreciation A/c', 'a', 2, 3, 'A sale below book value creates a loss.', 'Loss on Sale of Asset A/c is debited for the shortfall. Profit on Sale applies when proceeds exceed book value.'),
        ('acc11-07-sd-0027', 7, 'Loss on sale of a fixed asset is ultimately transferred to:', 'Debit side of Profit & Loss A/c', 'Credit side of Profit & Loss A/c', 'a', 2, 3, 'Losses are charged against business profit.', 'A loss on sale is transferred to the debit side of Profit and Loss A/c. The credit side records income and gains.'),
        ('acc11-07-sd-0028', 7, 'At the end of an accounting year, the credit balance entry ''By Balance c/d'' in an Asset Account represents:', 'The scrap value realised on discarding old machines', 'The written down value (closing book value) of the asset carried to the next year', 'b', 2, 3, 'The closing asset balance is carried into the next period.', 'By Balance c/d represents the asset’s closing written down value carried forward. It is not cash collected or profit earned.'),
        ('acc11-08-sd-0001', 8, 'What can still occur in computerized accounting systems?', 'Occurrence of errors in accounting records', 'Calculation of depreciation', 'a', 1, 3, 'Automation does not eliminate every bookkeeping mistake.', 'Errors can still occur in computerized accounting; depreciation calculation is a normal accounting task, not the issue being tested.'),
        ('acc11-08-sd-0002', 8, 'When one-sided errors are located AFTER the preparation of the Trial Balance, they are rectified with the help of:', 'Suspense Account', 'Trading Account', 'a', 1, 3, 'Recall the temporary account used for Trial Balance differences.', 'A Suspense Account temporarily records a Trial Balance difference while one-sided errors are rectified; the Trading Account serves a different purpose.'),
        ('acc11-08-sd-0003', 8, 'In which book of original entry are rectification journal entries recorded?', 'Cash Book', 'Journal Proper', 'b', 1, 3, 'Think of the book used for journal entries that do not fit special-purpose books.', 'Rectification journal entries are recorded in Journal Proper; the Cash Book records cash and bank transactions.'),
        ('acc11-08-sd-0004', 8, 'What happens to the Suspense Account once all one-sided errors have been located and rectified?', 'It automatically closes with a nil balance', 'It permanently maintains a debit balance transferred to the Balance Sheet', 'a', 1, 3, 'This account is temporary, not a permanent source of balance.', 'Once all relevant one-sided errors are rectified, the Suspense Account closes with a nil balance; it does not retain a permanent debit balance.'),
        ('acc11-08-sd-0005', 8, 'What is the term used for taking the total more than actual while closing books of accounts?', 'Undercasting', 'Overcasting', 'b', 1, 3, 'The term describes a total that is higher than the actual amount.', 'Overcasting means totaling an amount too high; undercasting means totaling it too low.'),
        ('acc11-08-sd-0006', 8, 'Unintentional omission or commission of amounts and accounts while recording transactions is termed as an:', 'Fraud', 'Error', 'b', 1, 3, 'Think of the general term for an unintentional bookkeeping mistake.', 'An unintentional omission or commission in recording accounts is an error; fraud involves deliberate deception.'),
        ('acc11-09-sd-0001', 9, 'The balancing figure of a Trading Account represents which of the following?', 'Gross Profit or Gross Loss', 'Net Profit or Net Loss', 'a', 1, 3, 'Recall what the Trading Account measures.', 'The Trading Account’s balancing figure is Gross Profit or Gross Loss. Net Profit or Net Loss is determined by the Profit and Loss Account.'),
        ('acc11-09-sd-0002', 9, 'The balancing figure of the Profit and Loss Account reveals:', 'Gross Profit or Gross Loss', 'Net Profit or Net Loss', 'b', 1, 3, 'Recall what the Profit and Loss Account measures.', 'The Profit and Loss Account’s balancing figure is Net Profit or Net Loss. Gross Profit or Gross Loss is determined by the Trading Account.'),
        ('acc11-09-sd-0003', 9, 'What is the primary function of a Balance Sheet in Final Accounts?', 'To calculate the gross trading margin earned during the accounting year', 'To show the financial position of assets and liabilities at a given period of time', 'b', 1, 3, 'Think of the statement that summarizes assets and liabilities.', 'A Balance Sheet shows the business’s financial position through its assets and liabilities. Gross trading margin is determined by the Trading Account.'),
        ('acc11-09-sd-0004', 9, 'Trading Account is classified under which type of account?', 'Nominal Account', 'Real Account', 'a', 1, 3, 'Classify an account used to determine trading results.', 'A Trading Account is a nominal account because it is prepared to determine gross profit or loss. A real account records assets.'),
        ('acc11-09-sd-0005', 9, 'In trading terminology, unsold goods at the beginning of an accounting year are called:', 'Opening Stock', 'Closing Stock', 'a', 1, 3, 'Think of goods on hand at the start of the year.', 'Unsold goods carried into the beginning of the accounting year are Opening Stock. Closing Stock refers to unsold goods at year-end.'),
        ('acc11-09-sd-0006', 9, 'Closing Stock is always valued in the Final Accounts at:', 'Cost or market price, whichever is more', 'Cost or market price, whichever is less', 'b', 1, 3, 'Recall the conservative stock-valuation rule.', 'Closing stock is valued at cost or market price, whichever is less. Using whichever is more can overstate stock.'),
        ('acc11-09-sd-0007', 9, 'Which of the following transactions must be debited to Purchases Account and included in the Trading Account?', 'Purchase of merchandise/goods meant for resale', 'Purchase of office furniture for business use', 'a', 2, 3, 'Purchases Account records goods acquired for resale.', 'Merchandise bought for resale is recorded in Purchases Account. Office furniture is a fixed asset, not goods purchased for resale.'),
        ('acc11-09-sd-0008', 9, 'Return Outwards is another accounting name for:', 'Sales Returns', 'Purchase Returns', 'b', 1, 3, 'Recall the alternative name for goods returned to suppliers.', 'Return Outwards means Purchase Returns: goods sent back to suppliers. Sales Returns are goods returned by customers.'),
        ('acc11-09-sd-0009', 9, 'How are Return Inwards treated in the preparation of the Trading Account?', 'Deducted from gross Sales on the credit side', 'Added to Purchases on the debit side', 'a', 2, 3, 'Customer returns reduce the sales figure.', 'Return Inwards are deducted from gross Sales on the credit side of the Trading Account. Adding them to Purchases would classify them incorrectly.'),
        ('acc11-09-sd-0010', 9, 'Direct expenses in final accounts are defined as expenses incurred for:', 'Office management and executive staff salaries', 'Purchase of goods, production of goods, and purchase expenses', 'b', 1, 3, 'Direct expenses relate closely to acquiring or producing goods.', 'Direct expenses relate to purchasing or producing goods. Office management and executive salaries are generally indirect expenses.'),
        ('acc11-09-sd-0011', 9, 'When an item appears as ''Wages & Salaries'' in the Trial Balance, where should it be debited?', 'Profit & Loss Account', 'Trading Account', 'b', 2, 3, 'Consider the usual classification of wages in a Trial Balance.', 'Wages appearing in the Trial Balance are generally debited to the Trading Account as a direct expense. Indirect expenses go to the Profit and Loss Account.'),
        ('acc11-09-sd-0012', 9, 'When the credit side of the Profit and Loss Account exceeds its debit side, the resulting balance is:', 'Net Profit', 'Net Loss', 'a', 1, 3, 'A credit-side excess in the Profit and Loss Account is a profit.', 'When the credit side exceeds the debit side, the result is Net Profit. Net Loss occurs when the debit side exceeds the credit side.'),
        ('acc11-09-sd-0013', 9, 'Why does a Balance Sheet NOT have ''To'' or ''By'' written against its items?', 'Because it records only cash transactions', 'Because it is a statement of financial position and not a ledger account', 'b', 2, 3, 'Think about whether a Balance Sheet is a ledger account or a statement.', 'A Balance Sheet is a statement of financial position, not a ledger account, so its items are not prefixed by ‘To’ or ‘By’.'),
        ('acc11-09-sd-0014', 9, 'Which category of accounts NEVER appears in the Balance Sheet?', 'Nominal Accounts', 'Personal Accounts', 'a', 1, 3, 'Identify the account category closed to final accounts.', 'Nominal accounts are closed through the Trading and Profit and Loss Accounts and do not appear as such in the Balance Sheet. Personal accounts can represent balances owed or receivable.'),
        ('acc11-09-sd-0015', 9, 'Depreciation is defined  as:', 'Gradual and continuous decrease or reduction in the value of fixed assets', 'Sudden accidental destruction of goods by fire or natural calamity', 'a', 1, 3, 'Depreciation describes a gradual change in fixed-asset value.', 'Depreciation is the gradual reduction in the value of fixed assets. Sudden destruction by fire is a loss by accident, not depreciation.'),
        ('acc11-09-sd-0016', 9, 'Expenses incurred during the current accounting year but not yet paid are known as:', 'Prepaid Expenses', 'Outstanding Expenses', 'b', 1, 3, 'These expenses have been incurred but remain unpaid.', 'Outstanding Expenses are incurred during the current period but not yet paid. Prepaid Expenses have been paid in advance for a future period.'),
        ('acc11-09-sd-0017', 9, 'Expenses paid during the current year in advance for the subsequent period are termed:', 'Prepaid (Unexpired) Expenses', 'Outstanding Expenses', 'a', 1, 3, 'These expenses are paid before the period they relate to.', 'Prepaid Expenses are paid in advance for a subsequent period. Outstanding Expenses have been incurred but remain unpaid.'),
        ('acc11-09-sd-0018', 9, 'Income earned during the accounting year but not yet received by the year-end is classified as:', 'Pre-received Income', 'Accrued Income (Outstanding Income)', 'b', 1, 3, 'The income has been earned but cash has not arrived.', 'Accrued Income has been earned but not yet received by year-end. Pre-received income is received before it is earned.'),
        ('acc11-09-sd-0019', 9, 'In accounting, debts that are irrecoverable from customers are called:', 'Bad Debts', 'Doubtful Debts', 'a', 1, 3, 'These debts cannot be recovered from customers.', 'Bad Debts are amounts considered irrecoverable from customers. Doubtful Debts may still be recovered, but collection is uncertain.'),
        ('acc11-09-sd-0020', 9, 'Why is a Reserve for Doubtful Debts (R.D.D.) created in final accounts?', 'To record debts that are already settled and received in cash', 'To provide for anticipated loss on debtors whose recovery is doubtful based on past experience', 'b', 2, 3, 'The reserve anticipates possible non-recovery from customers.', 'A Reserve for Doubtful Debts provides for expected losses on debts that may not be collected. Debts already received in cash do not require such a provision.'),
        ('acc11-09-sd-0021', 9, 'R.D.D. appearing in the Trial Balance is referred to as:', 'Old R.D.D. (Existing R.D.D.)', 'New R.D.D.', 'a', 1, 3, 'A reserve already present in the Trial Balance is the existing one.', 'R.D.D. already appearing in the Trial Balance is called Old R.D.D. or Existing R.D.D. New R.D.D. is calculated for the current final accounts.'),
        ('acc11-09-sd-0022', 9, 'How is Goodwill classified in the Balance Sheet?', 'Fictitious Asset', 'Intangible Fixed Asset (not a fictitious asset)', 'b', 1, 3, 'Goodwill has value but no physical form.', 'Goodwill is an intangible fixed asset because it has value without physical substance. It is not a fictitious asset.'),
        ('acc11-09-sd-0023', 9, 'Bank Overdraft is classified and shown in the Balance Sheet as a/an:', 'Current / External Liability', 'Current Asset', 'a', 1, 3, 'An overdraft is money owed to the bank.', 'A Bank Overdraft is a short-term amount owed to the bank, so it is a current external liability. It is not an asset.'),
        ('acc11-09-sd-0024', 9, 'In a Trial Balance containing Trade Expenses, Salaries, and Office Expenses, Trade Expenses should be:', 'Credited to Trading Account', 'Debited to Profit & Loss Account', 'b', 2, 3, 'Trade Expenses are treated as indirect operating expenses.', 'Trade Expenses are generally indirect expenses and are debited to the Profit and Loss Account. They are not credited to the Trading Account.'),
        ('acc11-09-sd-0025', 9, 'Motive Power, Fuel, Gas, and Water are recorded in:', 'Debit side of Profit and Loss Account', 'Debit side of Trading Account', 'b', 1, 3, 'These utilities support factory operations and production.', 'Motive power, fuel, gas, and water used in production are direct expenses debited to the Trading Account. Indirect operating expenses go to the Profit and Loss Account.'),
        ('acc11-09-sd-0026', 9, 'Royalties paid on production/goods are debited to:', 'Trading Account', 'Profit & Loss Account', 'a', 1, 3, 'Production-related royalties are a direct expense.', 'Royalties paid on production or goods are direct costs and are debited to the Trading Account. The Profit and Loss Account records indirect expenses.'),
        ('acc11-09-sd-0027', 9, 'Discount received from creditors on prompt payment is an indirect income and is transferred to:', 'Credit side of Trading Account', 'Credit side of Profit & Loss Account', 'b', 1, 3, 'Discount received is an indirect income.', 'Discount received from creditors is an indirect income credited to the Profit and Loss Account. The Trading Account records trading results and direct items.'),
        ('acc11-09-sd-0028', 9, 'When an item ''Loss by fire ₹1,650'' appears directly as a debit balance in the Trial Balance, how is it treated?', 'Debited to Profit & Loss Account only', 'Debited to Trading Account only', 'a', 2, 3, 'A loss already recorded in the Trial Balance has one effect.', 'A loss by fire appearing directly in the Trial Balance is debited to the Profit and Loss Account only. It is not a direct trading expense.'),
        ('acc11-10-sd-0001', 10, 'For which type of business organization is the Single Entry System considered most suitable?', 'Small size business concerns with a limited number of transactions', 'Large multinational corporations with thousands of daily transactions', 'a', 1, 3, 'Think about the size of the business and its transaction volume.', 'The Single Entry System is generally suited to small businesses with relatively few transactions. Large multinational corporations usually need more complete accounting records.'),
        ('acc11-10-sd-0002', 10, 'Which classes of accounts are completely omitted or not maintained under the Single Entry System?', 'Personal accounts of creditors and debtors', 'Real and Nominal accounts', 'b', 1, 3, 'Recall which account classes are omitted in this system.', 'Real and Nominal accounts are generally not maintained under the Single Entry System. Personal accounts of debtors and creditors are commonly kept.'),
        ('acc11-10-sd-0003', 10, 'Single Entry System is described in the text as an unsystematic combination of which of the following?', 'Double entry, Triple entry, and Reverse entry', 'Single entry, Double entry, and No Entry', 'b', 1, 3, 'Recall the types of entry combined in this system.', 'The Single Entry System is an unsystematic combination of single entry, double entry, and no entry. Triple entry and reverse entry are not the stated combination.'),
        ('acc11-10-sd-0004', 10, 'What is a Statement of Affairs?', 'A statement of Assets and Liabilities prepared under the Single Entry System', 'A statement of all cash receipts and payments during a financial year', 'a', 1, 3, 'Think of the information a Statement of Affairs presents.', 'A Statement of Affairs lists assets and liabilities under the Single Entry System. A statement of cash receipts and payments records cash movements instead.'),
        ('acc11-10-sd-0005', 10, 'In the format of a Statement of Affairs, which items are recorded on the left-hand side and right-hand side, respectively?', 'Left-hand side records Assets; Right-hand side records Liabilities', 'Left-hand side records Liabilities; Right-hand side records Assets', 'b', 1, 3, 'Recall how assets and liabilities are arranged in the statement.', 'In a Statement of Affairs, liabilities appear on the left and assets on the right. Reversing these sides gives the wrong arrangement.'),
        ('acc11-10-sd-0006', 10, 'Which of the following items appears on the Liabilities side of a Statement of Affairs?', 'Bank Overdraft', 'Prepaid Expenses', 'a', 1, 3, 'Identify which item represents an amount owed by the business.', 'A bank overdraft is a liability because the business owes money to the bank. Prepaid expenses are assets.'),
        ('acc11-10-sd-0007', 10, 'Which of the following items appears on the Assets side of a Statement of Affairs?', 'Bank Loan', 'Prepaid Expenses', 'b', 1, 3, 'Look for an expense paid before it is used up.', 'Prepaid expenses are assets because they provide future economic benefit. A bank loan is a liability.'),
        ('acc11-10-sd-0008', 10, 'What are the two recognized methods of calculating profit or loss when books are maintained under Single Entry, as noted in the text?', 'Net Worth Method and Conversion Method', 'Cash Flow Method and Fund Flow Method', 'a', 1, 3, 'Recall the two methods used to find profit or loss.', 'The Net Worth Method and Conversion Method are the two recognized methods. Cash Flow and Fund Flow methods serve different purposes.'),
        ('acc11-10-sd-0009', 10, 'In the Net Worth Method, before accounting for adjustments, what indicates a Profit?', 'Closing Capital is more than Opening Capital', 'Closing Capital is equal to Opening Capital', 'a', 1, 3, 'Compare the opening and closing capital balances.', 'Closing capital greater than opening capital indicates a profit before adjustments. Equal balances alone do not indicate an increase in capital.'),
        ('acc11-10-sd-0010', 10, 'How is Additional Capital treated in the Statement of Profit or Loss?', 'It is added to Closing Capital', 'It is deducted from Closing Capital', 'b', 1, 3, 'Consider how new owner investment affects closing capital.', 'Additional capital is deducted from closing capital when calculating profit, because it is an owner contribution rather than earned profit. Adding it would inflate the result.'),
        ('acc11-10-sd-0011', 10, 'In what forms can Drawings be made by a proprietor as presented in the format of Statement of Profit or Loss?', 'In Cash and In Kind', 'Only in bank cheques', 'a', 1, 3, 'Recall the forms in which an owner may withdraw value.', 'Drawings may be made in cash or in kind. They are not limited to bank cheques.'),
        ('acc11-10-sd-0012', 10, 'How is Depreciation on fixed assets treated in the Statement of Profit or Loss?', 'It is added as an income and gain', 'It is deducted as an expense and loss', 'b', 1, 3, 'Think of depreciation as a cost of using fixed assets.', 'Depreciation is deducted as an expense or loss. It is not income or a gain.'),
        ('acc11-10-sd-0013', 10, 'Where does Reserve for Doubtful Debts (R.D.D.) appear in the Statement of Profit or Loss?', 'Under Expenses and Losses (to be deducted)', 'Under Incomes and Gains (to be added)', 'a', 1, 3, 'Recall where doubtful-debt reserves are treated in profit calculation.', 'Reserve for Doubtful Debts is treated under expenses and losses and deducted. It is not an income or gain.'),
        ('acc11-10-sd-0014', 10, 'How is Interest on Capital treated in the Statement of Profit or Loss?', 'Added under Incomes and Gains', 'Deducted under Expenses and Losses', 'b', 1, 3, 'Consider whether interest on the owner’s capital is a business cost.', 'Interest on Capital is deducted under Expenses and Losses in the Statement of Profit or Loss. It is not added as income.'),
        ('acc11-10-sd-0015', 10, 'How is Interest on Drawings treated in the Statement of Profit or Loss?', 'Added as an income to the business', 'Deducted as an operational expenditure', 'a', 1, 3, 'Think about who benefits when interest is charged on drawings.', 'Interest on Drawings is income to the business and is added. It is not an operating expense.'),
        ('acc11-10-sd-0016', 10, 'How are Outstanding (unpaid) Expenses treated in the Statement of Profit or Loss?', 'Added under Incomes and Gains', 'Deducted under Expenses and Losses', 'b', 1, 3, 'Recall how unpaid expenses affect the year’s profit.', 'Outstanding expenses are deducted under Expenses and Losses because they relate to the accounting period. They are not added as income.'),
        ('acc11-10-sd-0017', 10, 'How are Prepaid Expenses (Unexpired Expenses) treated in the Statement of Profit or Loss?', 'Added in the Statement of Profit or Loss', 'Deducted under Expenses and Losses', 'a', 1, 3, 'Think about expenses paid now for a future period.', 'Prepaid expenses are added back in the Statement of Profit or Loss because they do not belong to the current period’s expenses. They are not deducted as current expenses.')
    ) AS v (question_code, chapter_no, prompt, option_a, option_b, correct_option, difficulty, points, hint, explanation)
    JOIN chapters c ON c.chapter_no = v.chapter_no
    JOIN subjects sub ON sub.id = c.subject_id AND sub.code = 'accounts'
) AS s
ON t.question_code = s.question_code
WHEN MATCHED AND (t.chapter_id, t.prompt, t.option_a, t.option_b, t.correct_option, t.difficulty, t.points, t.hint, t.explanation) IS DISTINCT FROM (s.chapter_id, s.prompt, s.option_a, s.option_b, s.correct_option, s.difficulty, s.points, s.hint, s.explanation) THEN
    UPDATE SET chapter_id = s.chapter_id, prompt = s.prompt, option_a = s.option_a, option_b = s.option_b, correct_option = s.correct_option, difficulty = s.difficulty, points = s.points, hint = s.hint, explanation = s.explanation
WHEN NOT MATCHED THEN
    INSERT (question_code, chapter_id, prompt, option_a, option_b, correct_option, difficulty, points, hint, explanation) VALUES (s.question_code, s.chapter_id, s.prompt, s.option_a, s.option_b, s.correct_option, s.difficulty, s.points, s.hint, s.explanation)
WHEN NOT MATCHED BY SOURCE AND t.chapter_id IN (SELECT c.id FROM chapters c JOIN subjects sub ON sub.id = c.subject_id WHERE sub.code = 'accounts') THEN
    DELETE;
